-- 002_sprint0_multi_tenant.sql
-- Sprint 0: Multi-Tenant y Gestión de Cooperativas
-- Migración IDEMPOTENTE para bases de datos existentes.
-- Para instalaciones nuevas basta ejecutar bd.sql (ya incluye estos objetos).
--
-- Aplicación:
--   psql "postgresql://<usuario>:<password>@localhost:5433/cooperativa_db" -f migrations/002_sprint0_multi_tenant.sql

BEGIN;

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TABLE IF NOT EXISTS cooperativa (
    id             BIGSERIAL    PRIMARY KEY,
    uuid           UUID         NOT NULL DEFAULT gen_random_uuid(),
    nombre         VARCHAR(150) NOT NULL,
    razon_social   VARCHAR(200),
    nit            VARCHAR(20),
    correo         VARCHAR(150),
    telefono       VARCHAR(20),
    direccion      TEXT,
    estado         VARCHAR(20)  NOT NULL DEFAULT 'ACTIVO',
    fecha_creacion TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    fecha_baja     TIMESTAMPTZ,
    CONSTRAINT uq_cooperativa_uuid    UNIQUE (uuid),
    CONSTRAINT uq_cooperativa_nit     UNIQUE (nit),
    CONSTRAINT chk_cooperativa_estado CHECK (estado IN ('ACTIVO','INACTIVO'))
);

CREATE INDEX IF NOT EXISTS idx_cooperativa_estado ON cooperativa(estado);
CREATE INDEX IF NOT EXISTS idx_cooperativa_nombre ON cooperativa(nombre);

ALTER TABLE usuario
    ADD COLUMN IF NOT EXISTS cooperativa_id BIGINT REFERENCES cooperativa(id);

CREATE INDEX IF NOT EXISTS idx_usuario_cooperativa ON usuario(cooperativa_id);

-- rol.nombre no tiene UNIQUE en bd.sql, por eso no se usa ON CONFLICT
INSERT INTO rol (nombre, descripcion)
SELECT 'SUPERADMIN', 'Super Administrador SaaS: gestiona cooperativas (tenants)'
WHERE NOT EXISTS (SELECT 1 FROM rol WHERE nombre = 'SUPERADMIN');

COMMIT;

-- ============================================================
-- Migración 003: Tabla de Bitácora de Auditoría
-- Sprint 1 — Dashboard Admin + Audit Trail
-- Fecha: 2026-08-23
-- Revisada: 2026-09-24 — alineada a bd.sql y al modelo Bitacora
--   (sin CHECK de módulo, sin columnas duplicadas, sin datos de prueba)
-- ============================================================

BEGIN;

-- Si la tabla no existe, crearla con el esquema de bd.sql
CREATE TABLE IF NOT EXISTS bitacora (
    id          BIGSERIAL    PRIMARY KEY,
    usuario_id  BIGINT       NOT NULL REFERENCES usuario(id),
    modulo      VARCHAR(50)  NOT NULL,
    accion      VARCHAR(100) NOT NULL,
    descripcion TEXT,
    ip          VARCHAR(45),
    user_agent  TEXT,
    fecha_hora  TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

-- Columna multi-tenant (idempotente)
ALTER TABLE bitacora ADD COLUMN IF NOT EXISTS cooperativa_id BIGINT;

-- Foreign key cooperativa_id -> cooperativa(id) (idempotente)
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.table_constraints
        WHERE table_name = 'bitacora' AND constraint_name = 'fk_bitacora_cooperativa'
    ) THEN
        ALTER TABLE bitacora
            ADD CONSTRAINT fk_bitacora_cooperativa
            FOREIGN KEY (cooperativa_id) REFERENCES cooperativa(id) ON DELETE SET NULL;
    END IF;
END $$;

-- La versión anterior de esta migración agregaba un CHECK de módulo que no
-- coincide con los módulos que registra la aplicación (USUARIO, SOCIO,
-- AHORROS, APORTES, ROL, ...). Se retira en bases donde ya se aplicó.
ALTER TABLE bitacora DROP CONSTRAINT IF EXISTS chk_bitacora_modulo;

-- Índices para consultas frecuentes del dashboard
CREATE INDEX IF NOT EXISTS idx_bitacora_cooperativa ON bitacora (cooperativa_id, fecha_hora DESC);
CREATE INDEX IF NOT EXISTS idx_bitacora_usuario     ON bitacora (usuario_id);
CREATE INDEX IF NOT EXISTS idx_bitacora_modulo      ON bitacora (modulo, fecha_hora DESC);

COMMENT ON TABLE  bitacora        IS 'Registro de auditoría de acciones relevantes del sistema.';
COMMENT ON COLUMN bitacora.accion IS 'Identificador de la acción (ej. LOGIN, CREAR, ACTUALIZAR).';
COMMENT ON COLUMN bitacora.modulo IS 'Módulo origen de la acción.';

COMMIT;
-- Sprint 1: aislamiento real de socios y bitácora por cooperativa.
BEGIN;

ALTER TABLE socio
    ADD COLUMN IF NOT EXISTS cooperativa_id BIGINT REFERENCES cooperativa(id);

ALTER TABLE bitacora
    ADD COLUMN IF NOT EXISTS cooperativa_id BIGINT REFERENCES cooperativa(id);

CREATE INDEX IF NOT EXISTS idx_socio_cooperativa ON socio(cooperativa_id);
CREATE INDEX IF NOT EXISTS idx_bitacora_cooperativa ON bitacora(cooperativa_id, fecha_hora DESC);

-- Los registros históricos sin tenant quedan NULL deliberadamente: solo
-- SUPERADMIN puede verlos hasta que se asignen a una cooperativa.
COMMIT;
-- Sprint 1: apertura de cuentas de ahorro y certificados de aportacion.
BEGIN;

ALTER TABLE socio
    ADD COLUMN IF NOT EXISTS usuario_id BIGINT REFERENCES usuario(id);

CREATE INDEX IF NOT EXISTS idx_socio_usuario ON socio(usuario_id);
CREATE INDEX IF NOT EXISTS idx_cuenta_socio_estado ON cuenta_ahorro(socio_id, estado);
CREATE INDEX IF NOT EXISTS idx_certificado_socio ON certificado_aportacion(socio_id);

COMMIT;
-- Sprint 2: tipo de producto y monto de apertura en cuentas de ahorro;
-- titulos, valor unitario y correlativo en certificados de aportacion.
BEGIN;

-- ── Cuentas de ahorro ──────────────────────────────────────────────────────
ALTER TABLE cuenta_ahorro
    ADD COLUMN IF NOT EXISTS tipo_producto VARCHAR(20) NOT NULL DEFAULT 'VISTA';

DO $$ BEGIN
    ALTER TABLE cuenta_ahorro
        ADD CONSTRAINT chk_cuenta_tipo_producto CHECK (tipo_producto IN ('VISTA', 'PROGRAMADO'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- Los estados del criterio de aceptacion son Activa/Bloqueada/Cancelada
-- (el estado legado INACTIVA pasa a CANCELADA).
UPDATE cuenta_ahorro SET estado = 'CANCELADA' WHERE estado = 'INACTIVA';

DO $$ BEGIN
    ALTER TABLE cuenta_ahorro
        ADD CONSTRAINT chk_cuenta_estado CHECK (estado IN ('ACTIVA', 'BLOQUEADA', 'CANCELADA'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- ── Certificados de aportacion ───────────────────────────────────────────
ALTER TABLE certificado_aportacion
    ADD COLUMN IF NOT EXISTS numero_titulos INT NOT NULL DEFAULT 1,
    ADD COLUMN IF NOT EXISTS valor_unitario NUMERIC(12, 2) NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS correlativo INT;

-- Certificados existentes: se asume 1 titulo con valor unitario = monto ya emitido.
UPDATE certificado_aportacion SET valor_unitario = monto WHERE valor_unitario = 0;

-- ── Secuencias parametrizadas por cooperativa ───────────────────────────
-- Numeracion de cuentas de ahorro y correlativo oficial de certificados,
-- ambos independientes por tenant (cooperativa_id = 0 agrupa registros legados sin tenant).
CREATE TABLE IF NOT EXISTS secuencia_documento (
    cooperativa_id INT NOT NULL,
    tipo VARCHAR(30) NOT NULL,
    siguiente INT NOT NULL DEFAULT 1,
    PRIMARY KEY (cooperativa_id, tipo)
);

-- Asigna correlativo a certificados existentes segun su orden de emision, por cooperativa.
WITH numerados AS (
    SELECT ca.id,
           ROW_NUMBER() OVER (PARTITION BY COALESCE(s.cooperativa_id, 0) ORDER BY ca.id) AS rn,
           COALESCE(s.cooperativa_id, 0) AS coop
    FROM certificado_aportacion ca
    JOIN socio s ON s.id = ca.socio_id
)
UPDATE certificado_aportacion ca
SET correlativo = numerados.rn
FROM numerados
WHERE numerados.id = ca.id;

ALTER TABLE certificado_aportacion
    ALTER COLUMN correlativo SET NOT NULL;

-- Inicializa el contador de cada cooperativa a partir de lo ya emitido.
INSERT INTO secuencia_documento (cooperativa_id, tipo, siguiente)
SELECT COALESCE(s.cooperativa_id, 0), 'CERTIFICADO_APORTACION', COALESCE(MAX(ca.correlativo), 0) + 1
FROM certificado_aportacion ca
JOIN socio s ON s.id = ca.socio_id
GROUP BY COALESCE(s.cooperativa_id, 0)
ON CONFLICT (cooperativa_id, tipo) DO NOTHING;

INSERT INTO secuencia_documento (cooperativa_id, tipo, siguiente)
SELECT COALESCE(s.cooperativa_id, 0), 'CUENTA_AHORRO', COUNT(*) + 1
FROM cuenta_ahorro c
JOIN socio s ON s.id = c.socio_id
GROUP BY COALESCE(s.cooperativa_id, 0)
ON CONFLICT (cooperativa_id, tipo) DO NOTHING;

COMMIT;

-- Sprint 3: transferencias entre cuentas propias.
-- Columna self-FK nullable para vincular las dos patas de una transferencia
-- (TRANSFERENCIA_SALIDA / TRANSFERENCIA_ENTRADA) en `transaccion`,
-- al estilo de `transaccion_reversion_id` (bd.sql).
BEGIN;

ALTER TABLE transaccion
    ADD COLUMN IF NOT EXISTS transaccion_contraparte_id INT REFERENCES transaccion(id);

CREATE INDEX IF NOT EXISTS idx_transaccion_contraparte ON transaccion(transaccion_contraparte_id);

COMMIT;
-- 008_seed_transferencias_demo.sql
-- Datos de DEMO/DEV para probar Transferencias entre Cuentas desde la app
-- móvil. NO es una migración de esquema -- solo datos. Todos los INSERT son
-- idempotentes: correrla de nuevo resetea los saldos a estos valores.
--
-- Aplicación (contenedor Docker "coopDB" de compose.yml ya levantado):
--   docker exec -i coopDB psql -U yimysito -d cooperativa_db < migrations/008_seed_transferencias_demo.sql
--
-- Crea (si no existen ya, ej. por seed_users.py):
--   - Cooperativa de Prueba SI2
--   - Rol SOCIO
--   - Usuarios socio@test.com y socio2@test.com (contraseña 'Password123' para ambos)
--   - Los socios (KYC) ligados a esos usuarios
--
-- Y siempre (re)crea estas cuentas de ahorro:
--   socio@test.com  -> AH-DEMO-001 (BOB 2500.00), AH-DEMO-002 (BOB 850.50, 100.00 bloqueado),
--                      AH-DEMO-003 (USD 300.00)  [para probar el desglose multi-moneda del saldo]
--   socio2@test.com -> AH-DEMO-101 (BOB 1000.00)  [para probar transferir a "cuenta ajena" -> 404]

BEGIN;

-- ── Cooperativa de prueba ──────────────────────────────────────────────────
INSERT INTO cooperativa (nombre, razon_social, nit, correo, telefono, direccion, estado)
VALUES (
    'Cooperativa de Prueba SI2', 'Cooperativa de Prueba SI2 Ltda.', '9988776655',
    'contacto@cooptest.bo', '+591 3 9876543', 'Av. Testing #001, Santa Cruz', 'ACTIVO'
)
ON CONFLICT (nit) DO NOTHING;

-- ── Rol SOCIO (rol.nombre no tiene UNIQUE en este esquema, se evita ON CONFLICT) ──
INSERT INTO rol (nombre, descripcion)
SELECT 'SOCIO', 'Socio / Cliente: acceso limitado a su propia información dentro de la cooperativa'
WHERE NOT EXISTS (SELECT 1 FROM rol WHERE nombre = 'SOCIO');

-- ── Usuarios SOCIO (hash bcrypt de 'Password123') ─────────────────────────
INSERT INTO usuario (rol_id, cooperativa_id, nombre, contrasena, correo, estado)
SELECT
    (SELECT id FROM rol WHERE nombre = 'SOCIO'),
    (SELECT id FROM cooperativa WHERE nombre = 'Cooperativa de Prueba SI2'),
    'Sofia Socia',
    '$2b$12$GxvnpVLgq2DSYdi9eLlsQOE8THSkLE8aih09mGZNV2HY/pEEA/dCi',
    'socio@test.com',
    'ACTIVO'
ON CONFLICT (correo) DO NOTHING;

INSERT INTO usuario (rol_id, cooperativa_id, nombre, contrasena, correo, estado)
SELECT
    (SELECT id FROM rol WHERE nombre = 'SOCIO'),
    (SELECT id FROM cooperativa WHERE nombre = 'Cooperativa de Prueba SI2'),
    'Mateo Terceros',
    '$2b$12$GxvnpVLgq2DSYdi9eLlsQOE8THSkLE8aih09mGZNV2HY/pEEA/dCi',
    'socio2@test.com',
    'ACTIVO'
ON CONFLICT (correo) DO NOTHING;

-- ── Socios (KYC) ligados a esos usuarios ──────────────────────────────────
INSERT INTO socio (cooperativa_id, ci, nombre, apellido, correo, estado, usuario_id)
SELECT
    (SELECT id FROM cooperativa WHERE nombre = 'Cooperativa de Prueba SI2'),
    '5551234', 'Sofia', 'Socia', 'socio@test.com', 'ACTIVO',
    (SELECT id FROM usuario WHERE correo = 'socio@test.com')
ON CONFLICT (ci) DO UPDATE SET usuario_id = EXCLUDED.usuario_id, estado = 'ACTIVO';

INSERT INTO socio (cooperativa_id, ci, nombre, apellido, correo, estado, usuario_id)
SELECT
    (SELECT id FROM cooperativa WHERE nombre = 'Cooperativa de Prueba SI2'),
    '5559876', 'Mateo', 'Terceros', 'socio2@test.com', 'ACTIVO',
    (SELECT id FROM usuario WHERE correo = 'socio2@test.com')
ON CONFLICT (ci) DO UPDATE SET usuario_id = EXCLUDED.usuario_id, estado = 'ACTIVO';

-- ── Cuentas de ahorro ──────────────────────────────────────────────────────
-- socio@test.com: dos cuentas BOB (para transferir entre sí) + una USD
-- (para probar que el saldo se desglosa por moneda, nunca se suma).
INSERT INTO cuenta_ahorro (numero, tipo_producto, saldo_disponible, saldo_bloqueado, estado, fecha_registro, socio_id, moneda_id)
SELECT 'AH-DEMO-001', 'VISTA', 2500.00, 0.00, 'ACTIVA', CURRENT_DATE,
       (SELECT id FROM socio WHERE ci = '5551234'),
       (SELECT id FROM moneda WHERE codigo_iso = 'BOB')
ON CONFLICT (numero) DO UPDATE SET
    saldo_disponible = EXCLUDED.saldo_disponible,
    saldo_bloqueado = EXCLUDED.saldo_bloqueado,
    estado = 'ACTIVA';

INSERT INTO cuenta_ahorro (numero, tipo_producto, saldo_disponible, saldo_bloqueado, estado, fecha_registro, socio_id, moneda_id)
SELECT 'AH-DEMO-002', 'PROGRAMADO', 850.50, 100.00, 'ACTIVA', CURRENT_DATE,
       (SELECT id FROM socio WHERE ci = '5551234'),
       (SELECT id FROM moneda WHERE codigo_iso = 'BOB')
ON CONFLICT (numero) DO UPDATE SET
    saldo_disponible = EXCLUDED.saldo_disponible,
    saldo_bloqueado = EXCLUDED.saldo_bloqueado,
    estado = 'ACTIVA';

INSERT INTO cuenta_ahorro (numero, tipo_producto, saldo_disponible, saldo_bloqueado, estado, fecha_registro, socio_id, moneda_id)
SELECT 'AH-DEMO-003', 'VISTA', 300.00, 0.00, 'ACTIVA', CURRENT_DATE,
       (SELECT id FROM socio WHERE ci = '5551234'),
       (SELECT id FROM moneda WHERE codigo_iso = 'USD')
ON CONFLICT (numero) DO UPDATE SET
    saldo_disponible = EXCLUDED.saldo_disponible,
    saldo_bloqueado = EXCLUDED.saldo_bloqueado,
    estado = 'ACTIVA';

-- socio2@test.com: una cuenta BOB, para probar transferir a "cuenta ajena" -> 404.
INSERT INTO cuenta_ahorro (numero, tipo_producto, saldo_disponible, saldo_bloqueado, estado, fecha_registro, socio_id, moneda_id)
SELECT 'AH-DEMO-101', 'VISTA', 1000.00, 0.00, 'ACTIVA', CURRENT_DATE,
       (SELECT id FROM socio WHERE ci = '5559876'),
       (SELECT id FROM moneda WHERE codigo_iso = 'BOB')
ON CONFLICT (numero) DO UPDATE SET
    saldo_disponible = EXCLUDED.saldo_disponible,
    saldo_bloqueado = EXCLUDED.saldo_bloqueado,
    estado = 'ACTIVA';

COMMIT;
-- Sprint 4: apertura de caja y operaciones de ventanilla.
BEGIN;

ALTER TABLE caja
    ADD COLUMN IF NOT EXISTS cooperativa_id BIGINT REFERENCES cooperativa(id);

ALTER TABLE caja
    ADD COLUMN IF NOT EXISTS monto_maximo_efectivo NUMERIC(12, 2)
    NOT NULL DEFAULT 50000.00;

-- Pre-existing data may hold several open sessions for the same user or caja,
-- which would make the unique indexes below fail. Keep only the most recent
-- open session per user and per caja; close the rest.
UPDATE control_caja
SET estado = 'CERRADA',
    fecha_cierre = COALESCE(fecha_cierre, now()),
    monto_cierre = COALESCE(monto_cierre, saldo_sistema)
WHERE estado = 'ABIERTA'
  AND (
    id NOT IN (
        SELECT DISTINCT ON (usuario_id) id FROM control_caja
        WHERE estado = 'ABIERTA'
        ORDER BY usuario_id, fecha_apertura DESC, id DESC
    )
    OR id NOT IN (
        SELECT DISTINCT ON (caja_id) id FROM control_caja
        WHERE estado = 'ABIERTA'
        ORDER BY caja_id, fecha_apertura DESC, id DESC
    )
  );

CREATE UNIQUE INDEX IF NOT EXISTS uq_control_caja_usuario_abierta
    ON control_caja (usuario_id)
    WHERE estado = 'ABIERTA';

CREATE UNIQUE INDEX IF NOT EXISTS uq_control_caja_caja_abierta
    ON control_caja (caja_id)
    WHERE estado = 'ABIERTA';

ALTER TABLE transaccion
    ADD COLUMN IF NOT EXISTS depositante_nombre VARCHAR(150);

ALTER TABLE transaccion
    ADD COLUMN IF NOT EXISTS depositante_ci VARCHAR(20);

COMMIT;
-- Sprint 4: arqueo y conciliación de caja.
BEGIN;

ALTER TABLE caja
    ADD COLUMN IF NOT EXISTS umbral_diferencia_arqueo NUMERIC(12, 2)
    NOT NULL DEFAULT 50.00;

CREATE TABLE IF NOT EXISTS arqueo_caja (
    id BIGSERIAL PRIMARY KEY,
    control_caja_id INT NOT NULL REFERENCES control_caja(id),
    usuario_id BIGINT NOT NULL REFERENCES usuario(id),
    supervisor_id BIGINT NULL REFERENCES usuario(id),
    fecha TIMESTAMPTZ NOT NULL DEFAULT now(),
    fecha_autorizacion TIMESTAMPTZ NULL,
    cierre BOOLEAN NOT NULL DEFAULT false,
    requiere_supervisor BOOLEAN NOT NULL,
    observacion TEXT NULL
);

CREATE TABLE IF NOT EXISTS arqueo_caja_moneda (
    id BIGSERIAL PRIMARY KEY,
    arqueo_id BIGINT NOT NULL REFERENCES arqueo_caja(id) ON DELETE CASCADE,
    moneda_id INT NOT NULL REFERENCES moneda(id),
    saldo_teorico NUMERIC(12, 2) NOT NULL,
    total_contado NUMERIC(12, 2) NOT NULL,
    diferencia NUMERIC(12, 2) NOT NULL,
    resultado VARCHAR(10) NOT NULL
        CHECK (resultado IN ('CUADRADO', 'SOBRANTE', 'FALTANTE'))
);

CREATE TABLE IF NOT EXISTS arqueo_caja_detalle (
    id BIGSERIAL PRIMARY KEY,
    arqueo_moneda_id BIGINT NOT NULL
        REFERENCES arqueo_caja_moneda(id) ON DELETE CASCADE,
    tipo VARCHAR(10) NOT NULL CHECK (tipo IN ('BILLETE', 'MONEDA')),
    denominacion NUMERIC(12, 2) NOT NULL,
    cantidad INT NOT NULL CHECK (cantidad >= 0),
    subtotal NUMERIC(12, 2) NOT NULL
);

COMMIT;
-- CU-W12 / CU-W16: withdrawal identification and formal cash closing.

ALTER TABLE transaccion
    ADD COLUMN IF NOT EXISTS retirante_tipo VARCHAR(10),
    ADD COLUMN IF NOT EXISTS retirante_nombre VARCHAR(150),
    ADD COLUMN IF NOT EXISTS retirante_ci VARCHAR(20);

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'chk_transaccion_retirante_tipo'
          AND conrelid = 'transaccion'::regclass
    ) THEN
        ALTER TABLE transaccion
            ADD CONSTRAINT chk_transaccion_retirante_tipo
            CHECK (retirante_tipo IS NULL OR retirante_tipo IN ('TITULAR', 'APODERADO'));
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS cierre_caja (
    id BIGSERIAL PRIMARY KEY,
    control_caja_id INT NOT NULL UNIQUE REFERENCES control_caja(id),
    arqueo_id BIGINT NOT NULL REFERENCES arqueo_caja(id),
    usuario_id BIGINT NOT NULL REFERENCES usuario(id),
    fecha TIMESTAMPTZ NOT NULL DEFAULT now(),
    observacion TEXT
);

CREATE TABLE IF NOT EXISTS cierre_caja_moneda (
    id BIGSERIAL PRIMARY KEY,
    cierre_id BIGINT NOT NULL REFERENCES cierre_caja(id) ON DELETE CASCADE,
    moneda_id INT NOT NULL REFERENCES moneda(id),
    monto_apertura NUMERIC(12,2) NOT NULL,
    total_depositos NUMERIC(12,2) NOT NULL,
    cantidad_depositos INT NOT NULL,
    total_retiros NUMERIC(12,2) NOT NULL,
    cantidad_retiros INT NOT NULL,
    cantidad_transferencias INT NOT NULL,
    saldo_teorico NUMERIC(12,2) NOT NULL,
    total_contado NUMERIC(12,2) NOT NULL,
    diferencia NUMERIC(12,2) NOT NULL,
    traspaso_boveda NUMERIC(12,2) NOT NULL
);
BEGIN;

ALTER TABLE declaracion_jurada_uif
    ADD COLUMN IF NOT EXISTS tipo_operacion VARCHAR(30),
    ADD COLUMN IF NOT EXISTS monto NUMERIC(14,2),
    ADD COLUMN IF NOT EXISTS moneda_id INT REFERENCES moneda(id),
    ADD COLUMN IF NOT EXISTS socio_id INT REFERENCES socio(id),
    ADD COLUMN IF NOT EXISTS realizado_por VARCHAR(10),
    ADD COLUMN IF NOT EXISTS tercero_nombre VARCHAR(150),
    ADD COLUMN IF NOT EXISTS tercero_ci VARCHAR(20),
    ADD COLUMN IF NOT EXISTS tercero_parentesco VARCHAR(50),
    ADD COLUMN IF NOT EXISTS actividad_economica VARCHAR(150),
    ADD COLUMN IF NOT EXISTS origen_detalle TEXT,
    ADD COLUMN IF NOT EXISTS destino_detalle TEXT,
    ADD COLUMN IF NOT EXISTS declara_bajo_juramento BOOLEAN NOT NULL DEFAULT false,
    ADD COLUMN IF NOT EXISTS fraccionada BOOLEAN NOT NULL DEFAULT false,
    ADD COLUMN IF NOT EXISTS usuario_id BIGINT REFERENCES usuario(id),
    ADD COLUMN IF NOT EXISTS cooperativa_id BIGINT REFERENCES cooperativa(id),
    ADD COLUMN IF NOT EXISTS fecha TIMESTAMPTZ NOT NULL DEFAULT now();

DO $$ BEGIN
    ALTER TABLE declaracion_jurada_uif ADD CONSTRAINT chk_uif_realizado_por
        CHECK (realizado_por IS NULL OR realizado_por IN ('TITULAR','TERCERO'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

ALTER TABLE deposito_plazo_fijo
    ADD COLUMN IF NOT EXISTS numero_certificado VARCHAR(30),
    ADD COLUMN IF NOT EXISTS modalidad_pago_interes VARCHAR(12) DEFAULT 'VENCIMIENTO',
    ADD COLUMN IF NOT EXISTS interes_bruto NUMERIC(12,2),
    ADD COLUMN IF NOT EXISTS retencion_rciva NUMERIC(12,2),
    ADD COLUMN IF NOT EXISTS interes_neto NUMERIC(12,2),
    ADD COLUMN IF NOT EXISTS origen_fondos VARCHAR(10),
    ADD COLUMN IF NOT EXISTS cuenta_origen_id INT REFERENCES cuenta_ahorro(id),
    ADD COLUMN IF NOT EXISTS cuenta_abono_id INT REFERENCES cuenta_ahorro(id),
    ADD COLUMN IF NOT EXISTS codigo_verificacion VARCHAR(16),
    ADD COLUMN IF NOT EXISTS dpf_origen_id INT REFERENCES deposito_plazo_fijo(id),
    ADD COLUMN IF NOT EXISTS declaracion_jurada_uif_id INT REFERENCES declaracion_jurada_uif(id),
    ADD COLUMN IF NOT EXISTS usuario_id BIGINT REFERENCES usuario(id),
    ADD COLUMN IF NOT EXISTS cooperativa_id BIGINT REFERENCES cooperativa(id),
    ADD COLUMN IF NOT EXISTS fecha_emision TIMESTAMPTZ DEFAULT now();

CREATE UNIQUE INDEX IF NOT EXISTS uq_dpf_numero_certificado
    ON deposito_plazo_fijo(numero_certificado) WHERE numero_certificado IS NOT NULL;

CREATE TABLE IF NOT EXISTS tasa_dpf (
    id SERIAL PRIMARY KEY,
    cooperativa_id BIGINT NOT NULL REFERENCES cooperativa(id),
    moneda_id INT NOT NULL REFERENCES moneda(id),
    plazo_min_dias INT NOT NULL,
    plazo_max_dias INT,
    tna NUMERIC(5,2) NOT NULL,
    CONSTRAINT uq_tasa_dpf_banda UNIQUE (cooperativa_id, moneda_id, plazo_min_dias)
);

CREATE TABLE IF NOT EXISTS dpf_cronograma (
    id BIGSERIAL PRIMARY KEY,
    deposito_plazo_fijo_id INT NOT NULL REFERENCES deposito_plazo_fijo(id) ON DELETE CASCADE,
    numero INT NOT NULL,
    fecha_pago DATE NOT NULL,
    dias INT NOT NULL,
    interes_bruto NUMERIC(12,2) NOT NULL,
    retencion_rciva NUMERIC(12,2) NOT NULL,
    interes_neto NUMERIC(12,2) NOT NULL,
    estado VARCHAR(10) NOT NULL DEFAULT 'PENDIENTE',
    CONSTRAINT uq_dpf_cronograma_numero UNIQUE (deposito_plazo_fijo_id, numero)
);

ALTER TABLE cooperativa
    ADD COLUMN IF NOT EXISTS dpf_permite_cancelacion_anticipada BOOLEAN NOT NULL DEFAULT true,
    ADD COLUMN IF NOT EXISTS dpf_tasa_penalizacion NUMERIC(5,2) NOT NULL DEFAULT 1.00;

ALTER TABLE liquidacion
    ADD COLUMN IF NOT EXISTS tipo VARCHAR(20),
    ADD COLUMN IF NOT EXISTS retencion_rciva NUMERIC(12,2),
    ADD COLUMN IF NOT EXISTS usuario_id BIGINT REFERENCES usuario(id),
    ADD COLUMN IF NOT EXISTS cuenta_abono_id INT REFERENCES cuenta_ahorro(id),
    ADD COLUMN IF NOT EXISTS dpf_renovado_id INT REFERENCES deposito_plazo_fijo(id);

INSERT INTO tasa_dpf (cooperativa_id, moneda_id, plazo_min_dias, plazo_max_dias, tna)
SELECT c.id, m.id, v.plazo_min, v.plazo_max, v.tna
FROM cooperativa c
CROSS JOIN moneda m
CROSS JOIN (VALUES
    ('BOB',30,59,2.00), ('BOB',60,89,2.50), ('BOB',90,179,3.00),
    ('BOB',180,359,4.00), ('BOB',360,719,5.50), ('BOB',720,1079,6.00),
    ('BOB',1080,NULL,6.50), ('USD',30,179,0.50), ('USD',180,359,1.00),
    ('USD',360,719,1.50), ('USD',720,NULL,2.00)
) AS v(codigo, plazo_min, plazo_max, tna)
WHERE m.codigo_iso = v.codigo
ON CONFLICT (cooperativa_id, moneda_id, plazo_min_dias) DO NOTHING;

COMMIT;

-- Idempotent, additive demo data for the cooperative application.
-- Run after bd.sql and ALL migrations 002–012, including 008: the DPF rate
-- bands come from 012, which only seeds them for cooperatives that already
-- exist, and the demo cooperative is created by 008. Existing caja/control_caja rows are
-- deliberately never updated; the historical sessions below use only the two
-- demo cajas named here and are inserted already CERRADA.
BEGIN;

DO $seed$
DECLARE
    v_coop_id BIGINT;
    v_role_admin SMALLINT;
    v_role_socio SMALLINT;
    v_role_cashier SMALLINT;
    v_role_credit SMALLINT;
    v_admin_id BIGINT;
    v_cashier_id BIGINT;
    v_credit_id BIGINT;
    v_bob_id INT;
    v_usd_id INT;
    v_socio_id BIGINT;
    v_user_id BIGINT;
    v_account_id BIGINT;
    v_caja1_id INT;
    v_caja2_id INT;
    v_control1_id INT;
    v_control2_id INT;
    v_arqueo1_id BIGINT;
    v_arqueo2_id BIGINT;
    v_cierre1_id BIGINT;
    v_cierre2_id BIGINT;
    v_dpf_id INT;
    v_dpf_old_id INT;
    v_dpf_new_id INT;
    v_liquidacion_id INT;
    v_seq INT;
    v_rate NUMERIC(5,2);
    v_amount NUMERIC(12,2);
    v_gross NUMERIC(12,2);
    v_tax NUMERIC(12,2);
    v_net NUMERIC(12,2);
    v_start DATE;
    v_maturity DATE;
    v_elapsed INT;
    v_period_count INT;
    v_period INT;
    v_days INT;
    v_cumulative_days INT;
    v_gross_part NUMERIC(12,2);
    v_tax_part NUMERIC(12,2);
    v_gross_so_far NUMERIC(12,2);
    v_tax_so_far NUMERIC(12,2);
    v_number VARCHAR(30);
    v_hash VARCHAR(16);
    v_scenario RECORD;
    v_tx RECORD;
    v_declaration_id INT;
    v_transfer_out INT;
    v_transfer_in INT;
    v_timestamp TIMESTAMP;
BEGIN
    -- Resolve/create the cooperative by its natural key; names are not unique
    -- in the schema, so fail closed if the target name is ambiguous.
    INSERT INTO cooperativa (nombre, razon_social, correo, telefono, direccion, estado)
    SELECT 'Cooperativa de Prueba SI2', 'Cooperativa de Prueba SI2 Ltda.',
           'contacto@cooptest.bo', '+591 3 9876543',
           'Av. Testing #001, Santa Cruz', 'ACTIVO'
    WHERE NOT EXISTS (
        SELECT 1 FROM cooperativa WHERE nombre = 'Cooperativa de Prueba SI2'
    );
    IF (SELECT count(*) FROM cooperativa WHERE nombre = 'Cooperativa de Prueba SI2') <> 1 THEN
        RAISE EXCEPTION 'La cooperativa de demo no existe de forma unívoca';
    END IF;
    SELECT id INTO v_coop_id
    FROM cooperativa WHERE nombre = 'Cooperativa de Prueba SI2';

    SELECT id INTO v_role_admin FROM rol WHERE nombre = 'ADMINISTRADOR' ORDER BY id LIMIT 1;
    SELECT id INTO v_role_socio FROM rol WHERE nombre = 'SOCIO' ORDER BY id LIMIT 1;
    SELECT id INTO v_role_cashier FROM rol WHERE nombre = 'CAJERO' ORDER BY id LIMIT 1;
    SELECT id INTO v_role_credit FROM rol WHERE nombre = 'OFICIAL_CREDITO' ORDER BY id LIMIT 1;
    SELECT id INTO v_bob_id FROM moneda WHERE codigo_iso = 'BOB';
    SELECT id INTO v_usd_id FROM moneda WHERE codigo_iso = 'USD';
    IF v_role_admin IS NULL OR v_role_socio IS NULL OR v_role_cashier IS NULL
       OR v_role_credit IS NULL OR v_bob_id IS NULL OR v_usd_id IS NULL THEN
        RAISE EXCEPTION 'Faltan roles o monedas requeridos por el seed';
    END IF;

    -- The only tenant assignment updates allowed by the task.
    UPDATE usuario u SET cooperativa_id = v_coop_id
    FROM rol r
    WHERE r.id = u.rol_id AND r.nombre <> 'SUPERADMIN'
      AND u.cooperativa_id IS NULL
      AND u.correo IN ('admin@gmail.com', 'acredito@cooperativa.com',
                       'rcontador@cooperativa.com', 'juan.perez@email.com');

    -- The base file supplies the password hash. admin@test.com is absent from
    -- bd.sql + migrations 002–012, but is explicitly required as the signed
    -- supervisor for the demo shortage; create it only when absent.
    INSERT INTO usuario (rol_id, cooperativa_id, nombre, contrasena, correo, estado)
    SELECT v_role_admin, v_coop_id, 'Administradora de Demo',
           '$2b$12$XtO2CMCiiQIhv/eT8FTFuu0XfV8qGZNqa/UhNJvQpnF4d5BEW6Ok2',
           'admin@test.com', 'ACTIVO'
    WHERE NOT EXISTS (SELECT 1 FROM usuario WHERE correo = 'admin@test.com');
    SELECT u.id INTO v_admin_id
    FROM usuario u JOIN rol r ON r.id = u.rol_id
    WHERE u.correo = 'admin@test.com' AND u.estado = 'ACTIVO'
      AND u.cooperativa_id = v_coop_id AND r.nombre = 'ADMINISTRADOR';
    IF v_admin_id IS NULL THEN
        RAISE EXCEPTION 'admin@test.com existe, pero no es administrador activo de la cooperativa demo';
    END IF;

    -- Two member logins are needed for the demo socios; never rewrite an
    -- existing account with either address.
    INSERT INTO usuario (rol_id, cooperativa_id, nombre, contrasena, correo, estado)
    SELECT v_role_socio, v_coop_id, 'Elena Flores',
           '$2b$12$XtO2CMCiiQIhv/eT8FTFuu0XfV8qGZNqa/UhNJvQpnF4d5BEW6Ok2',
           'demo.socia1@si2.test', 'ACTIVO'
    WHERE NOT EXISTS (SELECT 1 FROM usuario WHERE correo = 'demo.socia1@si2.test');
    INSERT INTO usuario (rol_id, cooperativa_id, nombre, contrasena, correo, estado)
    SELECT v_role_socio, v_coop_id, 'Marco Rojas',
           '$2b$12$XtO2CMCiiQIhv/eT8FTFuu0XfV8qGZNqa/UhNJvQpnF4d5BEW6Ok2',
           'demo.socio2@si2.test', 'ACTIVO'
    WHERE NOT EXISTS (SELECT 1 FROM usuario WHERE correo = 'demo.socio2@si2.test');

    FOR v_scenario IN
        SELECT * FROM (VALUES
            ('8877001 SC', 'Elena', 'Flores', 'ACTIVO',  'demo.socia1@si2.test'),
            ('8877002 SC', 'Marco', 'Rojas',  'ACTIVO',  'demo.socio2@si2.test'),
            ('8877003 LP', 'Ana',   'Quiroga','ACTIVO',  NULL),
            ('8877004 SC', 'Diego', 'Vargas', 'ACTIVO',  NULL),
            ('8877005 CB', 'Lucía', 'Choque', 'ACTIVO',  NULL),
            ('8877006 SC', 'Jorge', 'Salvatierra','ACTIVO',NULL),
            ('8877007 LP', 'Carla', 'Mendoza','ACTIVO',  NULL),
            ('8877008 SC', 'Pablo', 'Arce',   'INACTIVO',NULL)
        ) AS socios(ci, nombre, apellido, estado, correo)
    LOOP
        SELECT id INTO v_user_id FROM usuario WHERE correo = v_scenario.correo;
        IF NOT EXISTS (SELECT 1 FROM socio WHERE ci = v_scenario.ci) THEN
            INSERT INTO socio (cooperativa_id, ci, nombre, apellido, direccion,
                               telefono, correo, estado, fecha_registro, usuario_id)
            VALUES (v_coop_id, v_scenario.ci, v_scenario.nombre, v_scenario.apellido,
                    'Santa Cruz, Bolivia', '70000000', v_scenario.correo,
                    v_scenario.estado, CURRENT_DATE - 10, v_user_id);
        END IF;
        SELECT id INTO v_socio_id FROM socio WHERE ci = v_scenario.ci;
        IF v_socio_id IS NULL THEN
            RAISE EXCEPTION 'No se pudo resolver socio %', v_scenario.ci;
        END IF;
    END LOOP;

    SELECT id INTO v_cashier_id FROM usuario WHERE correo = 'ccajero@cooperativa.com';
    SELECT id INTO v_credit_id FROM usuario WHERE correo = 'acredito@cooperativa.com';
    IF v_cashier_id IS NULL OR v_credit_id IS NULL THEN
        RAISE EXCEPTION 'Falta el cajero u oficial de crédito base';
    END IF;

    -- Initialize/advance account sequence to at least the largest existing
    -- account suffix for this tenant, then consume one value only for a newly
    -- inserted natural-key account.
    INSERT INTO secuencia_documento (cooperativa_id, tipo, siguiente)
    SELECT v_coop_id::INT, 'CUENTA_AHORRO', COALESCE(MAX(substring(c.numero FROM
           ('^CA-' || lpad(v_coop_id::TEXT, 3, '0') || '-([0-9]{6})$'))::INT), 0) + 1
    FROM cuenta_ahorro c JOIN socio s ON s.id = c.socio_id
    WHERE s.cooperativa_id = v_coop_id
    ON CONFLICT (cooperativa_id, tipo) DO NOTHING;
    UPDATE secuencia_documento sd SET siguiente = GREATEST(sd.siguiente, COALESCE((
        SELECT MAX(substring(c.numero FROM
               ('^CA-' || lpad(v_coop_id::TEXT, 3, '0') || '-([0-9]{6})$'))::INT) + 1
        FROM cuenta_ahorro c JOIN socio s ON s.id = c.socio_id
        WHERE s.cooperativa_id = v_coop_id
    ), 1)) WHERE sd.cooperativa_id = v_coop_id::INT AND sd.tipo = 'CUENTA_AHORRO';

    FOR v_scenario IN
        SELECT * FROM (VALUES
            ('8877001 SC','BOB','VISTA',     5000.00,  70700.00),
            ('8877002 SC','BOB','VISTA',     5000.00,   5500.00),
            ('8877003 LP','BOB','PROGRAMADO',2000.00,  82000.00),
            ('8877004 SC','USD','VISTA',     1500.00,   1100.00),
            ('8877005 CB','USD','PROGRAMADO',1200.00,   1200.12),
            ('8877006 SC','BOB','VISTA',     3000.00,   3020.00),
            ('8877007 LP','BOB','PROGRAMADO',3000.00,   2000.00)
        ) AS accounts(ci, currency, product, opening_balance, final_balance)
    LOOP
        SELECT id INTO v_socio_id FROM socio WHERE ci = v_scenario.ci;
        SELECT id INTO v_account_id FROM cuenta_ahorro c
        WHERE c.socio_id = v_socio_id
          AND c.moneda_id = (SELECT id FROM moneda WHERE codigo_iso = v_scenario.currency)
          AND c.tipo_producto = v_scenario.product;
        IF v_account_id IS NULL THEN
            UPDATE secuencia_documento SET siguiente = siguiente + 1
            WHERE cooperativa_id = v_coop_id::INT AND tipo = 'CUENTA_AHORRO'
            RETURNING siguiente - 1 INTO v_seq;
            v_number := 'CA-' || lpad(v_coop_id::TEXT, 3, '0') || '-' || lpad(v_seq::TEXT, 6, '0');
            INSERT INTO cuenta_ahorro (numero, tipo_producto, saldo_disponible,
                                       saldo_bloqueado, estado, fecha_registro,
                                       socio_id, moneda_id)
            SELECT v_number, v_scenario.product, v_scenario.final_balance,
                   0, 'ACTIVA', CURRENT_DATE - 5, v_socio_id,
                   m.id FROM moneda m WHERE m.codigo_iso = v_scenario.currency
              AND NOT EXISTS (SELECT 1 FROM cuenta_ahorro WHERE numero = v_number);
            SELECT id INTO v_account_id FROM cuenta_ahorro WHERE numero = v_number;
        END IF;
        IF v_account_id IS NULL THEN
            RAISE EXCEPTION 'No se pudo resolver la cuenta demo de %', v_scenario.ci;
        END IF;
        v_timestamp := (CURRENT_DATE - 5)::TIMESTAMP + TIME '09:00';
        IF NOT EXISTS (SELECT 1 FROM transaccion WHERE tipo = 'APERTURA'
                       AND cuenta_ahorro_id = v_account_id AND canal = 'WEB'
                       AND monto = v_scenario.opening_balance) THEN
            INSERT INTO transaccion (tipo, monto, canal, fecha_hora, moneda_id, cuenta_ahorro_id)
            SELECT 'APERTURA', v_scenario.opening_balance, 'WEB', v_timestamp,
                   c.moneda_id, c.id FROM cuenta_ahorro c WHERE c.id = v_account_id;
        END IF;
    END LOOP;

    -- Demo boxes are inserted closed. Existing caja/control_caja rows are not
    -- updated or reused if an unrelated name happens to exist.
    INSERT INTO caja (nombre, estado, cooperativa_id, monto_maximo_efectivo,
                      umbral_diferencia_arqueo)
    SELECT 'Ventanilla 3 - Plan 3000', 'CERRADA', v_coop_id, 50000.00, 50.00
    WHERE NOT EXISTS (SELECT 1 FROM caja WHERE cooperativa_id = v_coop_id
                      AND nombre = 'Ventanilla 3 - Plan 3000');
    INSERT INTO caja (nombre, estado, cooperativa_id, monto_maximo_efectivo,
                      umbral_diferencia_arqueo)
    SELECT 'Ventanilla 4 - Equipetrol', 'CERRADA', v_coop_id, 50000.00, 50.00
    WHERE NOT EXISTS (SELECT 1 FROM caja WHERE cooperativa_id = v_coop_id
                      AND nombre = 'Ventanilla 4 - Equipetrol');
    SELECT id INTO v_caja1_id FROM caja WHERE cooperativa_id = v_coop_id
      AND nombre = 'Ventanilla 3 - Plan 3000' ORDER BY id LIMIT 1;
    SELECT id INTO v_caja2_id FROM caja WHERE cooperativa_id = v_coop_id
      AND nombre = 'Ventanilla 4 - Equipetrol' ORDER BY id LIMIT 1;
    IF v_caja1_id IS NULL OR v_caja2_id IS NULL THEN
        RAISE EXCEPTION 'No se pudieron resolver las cajas demo';
    END IF;

    -- Stable close observations are natural seed markers. Their controls are
    -- inserted as closed and never alter the pre-existing open session.
    IF NOT EXISTS (SELECT 1 FROM cierre_caja WHERE observacion = 'Seed demo SI2: cierre turno 1') THEN
        INSERT INTO control_caja (monto_apertura, monto_cierre, saldo_sistema,
                                  fecha_apertura, fecha_cierre, estado, caja_id, usuario_id)
        VALUES (1000.00, 150000.00, 150000.00,
                (CURRENT_DATE - 2)::TIMESTAMP + TIME '08:00',
                (CURRENT_DATE - 2)::TIMESTAMP + TIME '11:05',
                'CERRADA', v_caja1_id, v_cashier_id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM cierre_caja WHERE observacion = 'Seed demo SI2: cierre turno 2') THEN
        INSERT INTO control_caja (monto_apertura, monto_cierre, saldo_sistema,
                                  fecha_apertura, fecha_cierre, estado, caja_id, usuario_id)
        VALUES (500.00, 600.00, 700.00,
                (CURRENT_DATE - 1)::TIMESTAMP + TIME '08:00',
                (CURRENT_DATE - 1)::TIMESTAMP + TIME '11:05',
                'CERRADA', v_caja2_id, v_cashier_id);
    END IF;
    SELECT cc.id INTO v_control1_id FROM control_caja cc
    JOIN caja c ON c.id = cc.caja_id
    JOIN cierre_caja cl ON cl.control_caja_id = cc.id
    WHERE c.id = v_caja1_id AND cl.observacion = 'Seed demo SI2: cierre turno 1';
    SELECT cc.id INTO v_control2_id FROM control_caja cc
    JOIN caja c ON c.id = cc.caja_id
    JOIN cierre_caja cl ON cl.control_caja_id = cc.id
    WHERE c.id = v_caja2_id AND cl.observacion = 'Seed demo SI2: cierre turno 2';
    -- On the first run the closing rows do not exist yet; resolve the two new
    -- controls by their stable cashier/caja/opening-time marker.
    IF v_control1_id IS NULL THEN
        SELECT id INTO v_control1_id FROM control_caja
        WHERE caja_id = v_caja1_id AND usuario_id = v_cashier_id
          AND fecha_apertura::TIME = TIME '08:00'
        ORDER BY id DESC LIMIT 1;
    END IF;
    IF v_control2_id IS NULL THEN
        SELECT id INTO v_control2_id FROM control_caja
        WHERE caja_id = v_caja2_id AND usuario_id = v_cashier_id
          AND fecha_apertura::TIME = TIME '08:00'
        ORDER BY id DESC LIMIT 1;
    END IF;
    IF v_control1_id IS NULL OR v_control2_id IS NULL THEN
        RAISE EXCEPTION 'No se pudieron resolver los controles de caja demo';
    END IF;

    -- UIF declaration for the threshold deposit and the same-day structured
    -- second 40,000 BOB deposit. Natural-key guards avoid duplicate records.
    SELECT id INTO v_socio_id FROM socio WHERE ci = '8877001 SC';
    IF NOT EXISTS (SELECT 1 FROM declaracion_jurada_uif
                   WHERE cooperativa_id = v_coop_id AND socio_id = v_socio_id
                     AND tipo_operacion = 'DEPOSITO' AND monto = 70000.00
                     AND moneda_id = v_bob_id AND fraccionada = false
                     AND origen = 'ACTIVIDAD_COMERCIAL' AND destino = 'AHORRO') THEN
        INSERT INTO declaracion_jurada_uif
            (origen, destino, tipo_operacion, monto, moneda_id, socio_id,
             realizado_por, actividad_economica, origen_detalle, destino_detalle,
             declara_bajo_juramento, fraccionada, usuario_id, cooperativa_id, fecha)
        VALUES ('ACTIVIDAD_COMERCIAL', 'AHORRO', 'DEPOSITO', 70000.00, v_bob_id,
                v_socio_id, 'TITULAR', 'Comercio minorista',
                'Ingresos por venta de abarrotes', 'Ahorro en cuenta', true, false,
                v_cashier_id, v_coop_id, (CURRENT_DATE - 2)::TIMESTAMP + TIME '09:15');
    END IF;
    SELECT id INTO v_declaration_id FROM declaracion_jurada_uif
    WHERE cooperativa_id = v_coop_id AND socio_id = v_socio_id
      AND tipo_operacion = 'DEPOSITO' AND monto = 70000.00
      AND moneda_id = v_bob_id AND fraccionada = false
      AND origen = 'ACTIVIDAD_COMERCIAL' AND destino = 'AHORRO'
    ORDER BY id LIMIT 1;
    IF v_declaration_id IS NULL THEN RAISE EXCEPTION 'Falta declaración UIF de umbral'; END IF;

    SELECT id INTO v_socio_id FROM socio WHERE ci = '8877003 LP';
    IF NOT EXISTS (SELECT 1 FROM declaracion_jurada_uif
                   WHERE cooperativa_id = v_coop_id AND socio_id = v_socio_id
                     AND tipo_operacion = 'DEPOSITO' AND monto = 40000.00
                     AND moneda_id = v_bob_id AND fraccionada = true
                     AND origen = 'ACTIVIDAD_COMERCIAL' AND destino = 'AHORRO') THEN
        INSERT INTO declaracion_jurada_uif
            (origen, destino, tipo_operacion, monto, moneda_id, socio_id,
             realizado_por, actividad_economica, origen_detalle, destino_detalle,
             declara_bajo_juramento, fraccionada, usuario_id, cooperativa_id, fecha)
        VALUES ('ACTIVIDAD_COMERCIAL', 'AHORRO', 'DEPOSITO', 40000.00, v_bob_id,
                v_socio_id, 'TITULAR', 'Comercio minorista',
                'Acumulación de ventas del día', 'Ahorro en cuenta', true, true,
                v_cashier_id, v_coop_id, (CURRENT_DATE - 2)::TIMESTAMP + TIME '09:05');
    END IF;
    SELECT id INTO v_declaration_id FROM declaracion_jurada_uif
    WHERE cooperativa_id = v_coop_id AND socio_id = v_socio_id
      AND tipo_operacion = 'DEPOSITO' AND monto = 40000.00
      AND moneda_id = v_bob_id AND fraccionada = true
      AND origen = 'ACTIVIDAD_COMERCIAL' AND destino = 'AHORRO'
    ORDER BY id LIMIT 1;
    IF v_declaration_id IS NULL THEN RAISE EXCEPTION 'Falta declaración UIF fraccionada'; END IF;

    -- Cash movements. Their timestamps precede the matching arqueo.
    FOR v_tx IN
        SELECT * FROM (VALUES
            (1, 'DEPOSITO', 70000.00, '8877001 SC', (CURRENT_DATE - 2)::TIMESTAMP + TIME '09:15', 'Elena Flores', '8877001 SC', false),
            (1, 'DEPOSITO', 40000.00, '8877003 LP', (CURRENT_DATE - 2)::TIMESTAMP + TIME '09:00', 'Ana Quiroga', '8877003 LP', false),
            (1, 'DEPOSITO', 40000.00, '8877003 LP', (CURRENT_DATE - 2)::TIMESTAMP + TIME '09:05', 'Ana Quiroga', '8877003 LP', true),
            (1, 'RETIRO',    1000.00, '8877001 SC', (CURRENT_DATE - 2)::TIMESTAMP + TIME '09:30', 'Elena Flores', '8877001 SC', false),
            (2, 'DEPOSITO',   500.00, '8877002 SC', (CURRENT_DATE - 1)::TIMESTAMP + TIME '09:10', 'Marco Rojas', '8877002 SC', false),
            (2, 'RETIRO',     300.00, '8877002 SC', (CURRENT_DATE - 1)::TIMESTAMP + TIME '09:20', 'Carlos Apoderado', '7000111 SC', false),
            (2, 'DEPOSITO',   100.00, '8877004 SC', (CURRENT_DATE - 1)::TIMESTAMP + TIME '09:25', 'Diego Vargas', '8877004 SC', false)
        ) AS movements(session_no, kind, amount, ci, happened, person, ci_person, uif)
    LOOP
        SELECT id INTO v_socio_id FROM socio WHERE ci = v_tx.ci;
        SELECT id INTO v_account_id FROM cuenta_ahorro WHERE socio_id = v_socio_id
        ORDER BY id LIMIT 1;
        IF v_tx.session_no = 1 AND v_tx.kind = 'DEPOSITO' AND v_tx.amount = 70000.00 THEN
            SELECT id INTO v_declaration_id FROM declaracion_jurada_uif
            WHERE cooperativa_id = v_coop_id AND socio_id = v_socio_id
              AND tipo_operacion = 'DEPOSITO' AND monto = 70000.00 AND moneda_id = v_bob_id
              AND fraccionada = false ORDER BY id LIMIT 1;
        ELSIF v_tx.session_no = 1 AND v_tx.kind = 'DEPOSITO' AND v_tx.amount = 40000.00 AND v_tx.uif THEN
            SELECT id INTO v_declaration_id FROM declaracion_jurada_uif
            WHERE cooperativa_id = v_coop_id AND socio_id = v_socio_id
              AND tipo_operacion = 'DEPOSITO' AND monto = 40000.00 AND moneda_id = v_bob_id
              AND fraccionada = true ORDER BY id LIMIT 1;
        ELSE
            v_declaration_id := NULL;
        END IF;
        SELECT (fecha_apertura::DATE::TIMESTAMP + v_tx.happened::TIME)
        INTO v_timestamp FROM control_caja
        WHERE id = CASE WHEN v_tx.session_no = 1 THEN v_control1_id ELSE v_control2_id END;
        IF NOT EXISTS (
            SELECT 1 FROM transaccion t
            WHERE t.control_caja_id = CASE WHEN v_tx.session_no = 1 THEN v_control1_id ELSE v_control2_id END
              AND t.tipo = v_tx.kind AND t.monto = v_tx.amount
              AND t.canal = 'VENTANILLA' AND t.cuenta_ahorro_id = v_account_id
              AND t.fecha_hora = v_timestamp
        ) THEN
            INSERT INTO transaccion (tipo, monto, canal, fecha_hora, control_caja_id,
                                     moneda_id, cuenta_ahorro_id, depositante_nombre,
                                     depositante_ci, retirante_tipo, retirante_nombre,
                                     retirante_ci, declaracion_jurada_uif_id)
            SELECT v_tx.kind, v_tx.amount, 'VENTANILLA', v_timestamp,
                   CASE WHEN v_tx.session_no = 1 THEN v_control1_id ELSE v_control2_id END,
                   c.moneda_id, c.id,
                   CASE WHEN v_tx.kind = 'DEPOSITO' THEN v_tx.person END,
                   CASE WHEN v_tx.kind = 'DEPOSITO' THEN v_tx.ci_person END,
                   CASE WHEN v_tx.kind = 'RETIRO' AND v_tx.ci_person = v_tx.ci THEN 'TITULAR'
                        WHEN v_tx.kind = 'RETIRO' THEN 'APODERADO' END,
                   CASE WHEN v_tx.kind = 'RETIRO' THEN v_tx.person END,
                   CASE WHEN v_tx.kind = 'RETIRO' THEN v_tx.ci_person END,
                   v_declaration_id
            FROM cuenta_ahorro c WHERE c.id = v_account_id;
        END IF;
    END LOOP;

    -- A ventanilla transfer is represented by both linked ledger legs. The
    -- IDs are allocated dynamically from the table identity sequence.
    SELECT c.id INTO v_account_id FROM cuenta_ahorro c JOIN socio s ON s.id = c.socio_id
    WHERE s.ci = '8877001 SC' AND c.moneda_id = v_bob_id;
    SELECT id INTO v_socio_id FROM socio WHERE ci = '8877002 SC';
    IF NOT EXISTS (SELECT 1 FROM transaccion WHERE control_caja_id = v_control1_id
                   AND tipo = 'TRANSFERENCIA_SALIDA' AND cuenta_ahorro_id = v_account_id
                   AND monto = 300.00 AND canal = 'VENTANILLA'
                   AND fecha_hora = (SELECT fecha_apertura::DATE::TIMESTAMP + TIME '10:00'
                                     FROM control_caja WHERE id=v_control1_id))
       AND NOT EXISTS (SELECT 1 FROM transaccion WHERE control_caja_id = v_control1_id
                   AND tipo = 'TRANSFERENCIA_ENTRADA' AND cuenta_ahorro_id =
                       (SELECT id FROM cuenta_ahorro WHERE socio_id = v_socio_id AND moneda_id = v_bob_id)
                   AND monto = 300.00 AND canal = 'VENTANILLA'
                   AND fecha_hora = (SELECT fecha_apertura::DATE::TIMESTAMP + TIME '10:00'
                                     FROM control_caja WHERE id=v_control1_id)) THEN
        v_transfer_out := nextval(pg_get_serial_sequence('transaccion','id'))::INT;
        v_transfer_in := nextval(pg_get_serial_sequence('transaccion','id'))::INT;
        SELECT fecha_apertura::DATE::TIMESTAMP + TIME '10:00' INTO v_timestamp
        FROM control_caja WHERE id=v_control1_id;
        INSERT INTO transaccion (id, tipo, monto, canal, fecha_hora, control_caja_id,
                                 moneda_id, cuenta_ahorro_id, transaccion_contraparte_id)
        OVERRIDING SYSTEM VALUE
        VALUES (v_transfer_out, 'TRANSFERENCIA_SALIDA', 300.00, 'VENTANILLA',
                v_timestamp, v_control1_id,
                v_bob_id, v_account_id, v_transfer_in),
               (v_transfer_in, 'TRANSFERENCIA_ENTRADA', 300.00, 'VENTANILLA',
                v_timestamp, v_control1_id, v_bob_id,
                (SELECT id FROM cuenta_ahorro WHERE socio_id = v_socio_id AND moneda_id = v_bob_id),
                v_transfer_out);
    END IF;

    -- DPF correlation starts at the current tenant sequence and remains
    -- stable because each scenario is looked up by its socio/product tuple.
    INSERT INTO secuencia_documento (cooperativa_id, tipo, siguiente)
    SELECT v_coop_id::INT, 'DPF', COALESCE(MAX(substring(d.numero_certificado FROM '^DPF-([0-9]{6})$')::INT),0)+1
    FROM deposito_plazo_fijo d WHERE d.cooperativa_id = v_coop_id
    ON CONFLICT (cooperativa_id, tipo) DO NOTHING;
    UPDATE secuencia_documento sd SET siguiente = GREATEST(sd.siguiente, COALESCE((
        SELECT MAX(substring(d.numero_certificado FROM '^DPF-([0-9]{6})$')::INT)+1
        FROM deposito_plazo_fijo d WHERE d.cooperativa_id = v_coop_id
    ),1)) WHERE sd.cooperativa_id = v_coop_id::INT AND sd.tipo = 'DPF';

    FOR v_scenario IN
        SELECT * FROM (VALUES
            ('8877001 SC','BOB',1000.00,360,  0,'VIGENTE','VENCIMIENTO','CUENTA'),
            ('8877001 SC','BOB',2000.00, 90,-87,'VIGENTE','MENSUAL',    'CUENTA'),
            ('8877004 SC','USD', 500.00, 90,-95,'VIGENTE','VENCIMIENTO','CUENTA'),
            ('8877006 SC','BOB',1000.00,180,-200,'LIQUIDADO','VENCIMIENTO','CUENTA'),
            ('8877007 LP','BOB',1000.00, 60,-70,'RENOVADO','VENCIMIENTO','CUENTA'),
            ('8877005 CB','USD', 500.00, 60,-10,'CANCELADO','VENCIMIENTO','CUENTA')
        ) AS dpfs(ci, currency, amount, term, start_offset, state, modality, funding)
    LOOP
        SELECT s.id INTO v_socio_id FROM socio s WHERE s.ci = v_scenario.ci;
        SELECT c.id INTO v_account_id FROM cuenta_ahorro c JOIN moneda m ON m.id = c.moneda_id
        WHERE c.socio_id = v_socio_id AND m.codigo_iso = v_scenario.currency
        ORDER BY c.id LIMIT 1;
        v_amount := v_scenario.amount;
        IF NOT EXISTS (SELECT 1 FROM deposito_plazo_fijo d
                       WHERE d.cooperativa_id = v_coop_id AND d.socio_id = v_socio_id
                         AND d.moneda_id = (SELECT id FROM moneda WHERE codigo_iso = v_scenario.currency)
                         AND d.monto = v_amount AND d.plazo_dias = v_scenario.term
                         AND d.estado = v_scenario.state AND d.origen_fondos = v_scenario.funding
                         AND d.cuenta_origen_id = v_account_id AND d.dpf_origen_id IS NULL) THEN
            SELECT t.tna INTO v_rate FROM tasa_dpf t
            WHERE t.cooperativa_id = v_coop_id
              AND t.moneda_id = (SELECT id FROM moneda WHERE codigo_iso = v_scenario.currency)
              AND t.plazo_min_dias <= v_scenario.term
              AND (t.plazo_max_dias IS NULL OR t.plazo_max_dias >= v_scenario.term)
            ORDER BY t.plazo_min_dias DESC LIMIT 1;
            IF v_rate IS NULL THEN RAISE EXCEPTION 'No hay banda DPF para % días / %', v_scenario.term, v_scenario.currency; END IF;
            v_start := CURRENT_DATE + v_scenario.start_offset;
            v_maturity := v_start + v_scenario.term;
            v_gross := round(v_amount * v_rate * v_scenario.term / 36000.0, 2);
            IF v_scenario.currency = 'BOB' AND v_scenario.term >= 30 THEN
                v_tax := 0.00;
            ELSE
                v_tax := round(v_gross * 0.13, 2);
            END IF;
            v_net := v_gross - v_tax;
            UPDATE secuencia_documento SET siguiente = siguiente + 1
            WHERE cooperativa_id = v_coop_id::INT AND tipo = 'DPF'
            RETURNING siguiente - 1 INTO v_seq;
            v_number := 'DPF-' || lpad(v_seq::TEXT, 6, '0');
            SELECT left(encode(digest(concat_ws('|', v_number, s.ci,
                to_char(v_amount,'FM999999999999990.00'), v_scenario.currency,
                to_char(v_start,'YYYY-MM-DD'), to_char(v_maturity,'YYYY-MM-DD'),
                to_char(v_rate,'FM999999990.00')), 'sha256'),'hex'),16)
            INTO v_hash FROM socio s WHERE s.id = v_socio_id;
            INSERT INTO deposito_plazo_fijo
                (monto, tasa_interes_anual, plazo_dias, fecha_inicio, fecha_vencimiento,
                 interes_calculado, estado, socio_id, moneda_id, numero_certificado,
                 modalidad_pago_interes, interes_bruto, retencion_rciva, interes_neto,
                 origen_fondos, cuenta_origen_id, cuenta_abono_id, codigo_verificacion,
                 usuario_id, cooperativa_id)
            SELECT v_amount, v_rate, v_scenario.term, v_start, v_maturity, v_gross,
                   v_scenario.state, v_socio_id, m.id, v_number, v_scenario.modality,
                   v_gross, v_tax, v_net, v_scenario.funding, v_account_id,
                   v_account_id, v_hash, v_admin_id, v_coop_id
            FROM moneda m WHERE m.codigo_iso = v_scenario.currency
              AND NOT EXISTS (SELECT 1 FROM deposito_plazo_fijo WHERE numero_certificado = v_number);
        END IF;
        SELECT id INTO v_dpf_id FROM deposito_plazo_fijo d
        WHERE d.cooperativa_id = v_coop_id AND d.socio_id = v_socio_id
          AND d.moneda_id = (SELECT id FROM moneda WHERE codigo_iso = v_scenario.currency)
          AND d.monto = v_amount AND d.plazo_dias = v_scenario.term
          AND d.estado = v_scenario.state AND d.origen_fondos = v_scenario.funding
          AND d.cuenta_origen_id = v_account_id AND d.dpf_origen_id IS NULL
        ORDER BY d.id LIMIT 1;
        IF v_dpf_id IS NULL THEN RAISE EXCEPTION 'No se pudo resolver DPF demo de %', v_scenario.ci; END IF;

        -- Seed the issue debit for every account-funded DPF.
        IF NOT EXISTS (SELECT 1 FROM transaccion WHERE deposito_plazo_fijo_id = v_dpf_id
                       AND tipo = 'RETIRO' AND canal = 'WEB' AND cuenta_ahorro_id = v_account_id
                       AND liquidacion_id IS NULL) THEN
            INSERT INTO transaccion (tipo, monto, canal, fecha_hora, moneda_id,
                                     cuenta_ahorro_id, deposito_plazo_fijo_id)
            SELECT 'RETIRO', v_amount, 'WEB', d.fecha_inicio::TIMESTAMP + TIME '12:00',
                   d.moneda_id, v_account_id, d.id
            FROM deposito_plazo_fijo d WHERE d.id = v_dpf_id;
        END IF;

        -- Build the same rounded installment schedule as the application.
        SELECT d.tasa_interes_anual, d.monto, d.plazo_dias, d.fecha_inicio,
               d.interes_bruto, d.retencion_rciva
        INTO v_rate, v_amount, v_elapsed, v_start, v_gross, v_tax
        FROM deposito_plazo_fijo d WHERE d.id = v_dpf_id;
        v_period_count := CASE WHEN v_scenario.modality = 'MENSUAL'
                               THEN ceil(v_elapsed / 30.0)::INT ELSE 1 END;
        v_period := 0; v_cumulative_days := 0;
        v_gross_so_far := 0; v_tax_so_far := 0;
        WHILE v_period < v_period_count LOOP
            v_period := v_period + 1;
            v_days := CASE WHEN v_scenario.modality = 'MENSUAL'
                           THEN LEAST(30, v_elapsed - v_cumulative_days) ELSE v_elapsed END;
            v_cumulative_days := v_cumulative_days + v_days;
            IF v_period = v_period_count THEN
                v_gross_part := v_gross - v_gross_so_far;
                v_tax_part := v_tax - v_tax_so_far;
            ELSE
                v_gross_part := round(v_amount * v_rate * v_days / 36000.0, 2);
                IF v_scenario.currency = 'BOB' AND v_elapsed >= 30 THEN
                    v_tax_part := 0;
                ELSE
                    v_tax_part := round(v_gross_part * 0.13, 2);
                END IF;
            END IF;
            IF NOT EXISTS (SELECT 1 FROM dpf_cronograma WHERE deposito_plazo_fijo_id = v_dpf_id AND numero = v_period) THEN
                INSERT INTO dpf_cronograma (deposito_plazo_fijo_id, numero, fecha_pago, dias,
                                            interes_bruto, retencion_rciva, interes_neto, estado)
                VALUES (v_dpf_id, v_period, v_start + v_cumulative_days, v_days,
                        v_gross_part, v_tax_part, v_gross_part - v_tax_part, 'PENDIENTE');
            END IF;
            v_gross_so_far := v_gross_so_far + v_gross_part;
            v_tax_so_far := v_tax_so_far + v_tax_part;
        END LOOP;
    END LOOP;

    -- A new DPF created by renewal is linked to the stable RENOVADO origin.
    SELECT id INTO v_socio_id FROM socio WHERE ci = '8877007 LP';
    SELECT id INTO v_account_id FROM cuenta_ahorro WHERE socio_id = v_socio_id AND moneda_id = v_bob_id;
    SELECT id INTO v_dpf_old_id FROM deposito_plazo_fijo
    WHERE cooperativa_id = v_coop_id AND socio_id = v_socio_id AND monto = 1000.00
      AND plazo_dias = 60 AND estado = 'RENOVADO' AND dpf_origen_id IS NULL
    ORDER BY id LIMIT 1;
    IF v_dpf_old_id IS NULL THEN RAISE EXCEPTION 'Falta el DPF origen renovado'; END IF;
    IF NOT EXISTS (SELECT 1 FROM deposito_plazo_fijo WHERE dpf_origen_id = v_dpf_old_id) THEN
        SELECT t.tna INTO v_rate FROM tasa_dpf t
        WHERE t.cooperativa_id = v_coop_id AND t.moneda_id = v_bob_id
          AND t.plazo_min_dias <= 360 AND (t.plazo_max_dias IS NULL OR t.plazo_max_dias >= 360)
        ORDER BY t.plazo_min_dias DESC LIMIT 1;
        v_amount := 1004.17;
        v_start := CURRENT_DATE; v_maturity := v_start + 360;
        v_gross := round(v_amount * v_rate * 360 / 36000.0, 2);
        v_tax := 0; v_net := v_gross;
        UPDATE secuencia_documento SET siguiente = siguiente + 1
        WHERE cooperativa_id = v_coop_id::INT AND tipo = 'DPF'
        RETURNING siguiente - 1 INTO v_seq;
        v_number := 'DPF-' || lpad(v_seq::TEXT, 6, '0');
        SELECT left(encode(digest(concat_ws('|', v_number, s.ci,
            to_char(v_amount,'FM999999999999990.00'), 'BOB', to_char(v_start,'YYYY-MM-DD'),
            to_char(v_maturity,'YYYY-MM-DD'), to_char(v_rate,'FM999999990.00')),'sha256'),'hex'),16)
        INTO v_hash FROM socio s WHERE s.id = v_socio_id;
        INSERT INTO deposito_plazo_fijo
            (monto, tasa_interes_anual, plazo_dias, fecha_inicio, fecha_vencimiento,
             interes_calculado, estado, socio_id, moneda_id, numero_certificado,
             modalidad_pago_interes, interes_bruto, retencion_rciva, interes_neto,
             origen_fondos, cuenta_origen_id, cuenta_abono_id, codigo_verificacion,
             dpf_origen_id, usuario_id, cooperativa_id)
        VALUES (v_amount, v_rate, 360, v_start, v_maturity, v_gross, 'VIGENTE',
                v_socio_id, v_bob_id, v_number, 'VENCIMIENTO', v_gross, v_tax,
                v_net, 'CUENTA', v_account_id, v_account_id, v_hash,
                v_dpf_old_id, v_admin_id, v_coop_id);
    END IF;
    SELECT id INTO v_dpf_new_id FROM deposito_plazo_fijo WHERE dpf_origen_id = v_dpf_old_id ORDER BY id LIMIT 1;
    IF v_dpf_new_id IS NULL THEN RAISE EXCEPTION 'No se pudo resolver el nuevo DPF renovado'; END IF;

    -- Add the renewal's single maturity schedule.
    SELECT tasa_interes_anual, monto, fecha_inicio, interes_bruto, retencion_rciva
    INTO v_rate, v_amount, v_start, v_gross, v_tax FROM deposito_plazo_fijo WHERE id = v_dpf_new_id;
    IF NOT EXISTS (SELECT 1 FROM dpf_cronograma WHERE deposito_plazo_fijo_id = v_dpf_new_id AND numero = 1) THEN
        INSERT INTO dpf_cronograma (deposito_plazo_fijo_id, numero, fecha_pago, dias,
                                    interes_bruto, retencion_rciva, interes_neto, estado)
        VALUES (v_dpf_new_id, 1, v_start + 360, 360, v_gross, v_tax, v_gross-v_tax, 'PENDIENTE');
    END IF;
    -- Stable DPF liquidations. Unique deposito_plazo_fijo_id is used only for
    -- the actual schema constraint; the transaction rows are guarded by their
    -- logical DPF/liquidation/type signature.
    FOR v_scenario IN
        SELECT d.id, d.estado, d.monto, d.moneda_id, d.cuenta_abono_id,
               d.fecha_vencimiento, d.fecha_inicio, d.plazo_dias,
               d.tasa_interes_anual, d.interes_bruto, d.retencion_rciva,
               d.interes_neto, m.codigo_iso
        FROM deposito_plazo_fijo d JOIN moneda m ON m.id=d.moneda_id
        WHERE d.cooperativa_id=v_coop_id AND (
            (d.socio_id=(SELECT id FROM socio WHERE ci='8877006 SC') AND d.estado='LIQUIDADO' AND d.plazo_dias=180)
            OR (d.socio_id=(SELECT id FROM socio WHERE ci='8877005 CB') AND d.estado='CANCELADO' AND d.plazo_dias=60)
            OR (d.id=v_dpf_old_id AND d.estado='RENOVADO')
        )
    LOOP
        v_dpf_id := v_scenario.id;
        IF v_scenario.estado = 'CANCELADO' THEN
            v_elapsed := greatest(0, (CURRENT_DATE - v_scenario.fecha_inicio));
            v_gross := round(v_scenario.monto * 1.00 * v_elapsed / 36000.0, 2);
            IF v_scenario.codigo_iso = 'BOB' AND v_elapsed >= 30 THEN v_tax := 0;
            ELSE v_tax := round(v_gross * 0.13, 2); END IF;
            v_net := v_gross-v_tax;
            v_timestamp := CURRENT_DATE::TIMESTAMP + TIME '10:30';
        ELSE
            v_gross := v_scenario.interes_bruto;
            v_tax := v_scenario.retencion_rciva;
            v_net := v_scenario.interes_neto;
            v_timestamp := v_scenario.fecha_vencimiento::TIMESTAMP + TIME '12:00';
        END IF;
        INSERT INTO liquidacion (monto_capital_retornado, monto_interes_pagado,
                                 tipo_operacion, fecha, deposito_plazo_fijo_id,
                                 tipo, retencion_rciva, usuario_id, cuenta_abono_id,
                                 dpf_renovado_id)
        SELECT v_scenario.monto, v_net,
               CASE v_scenario.estado WHEN 'LIQUIDADO' THEN 'LIQUIDACION'
                    WHEN 'CANCELADO' THEN 'CANCELACION' ELSE 'RENOVACION' END,
               v_timestamp, v_dpf_id,
               CASE v_scenario.estado WHEN 'LIQUIDADO' THEN 'LIQUIDACION'
                    WHEN 'CANCELADO' THEN 'CANCELACION' ELSE 'RENOVACION' END,
               v_tax, v_admin_id, v_scenario.cuenta_abono_id,
               CASE WHEN v_scenario.estado='RENOVADO' THEN v_dpf_new_id END
        WHERE NOT EXISTS (SELECT 1 FROM liquidacion WHERE deposito_plazo_fijo_id=v_dpf_id);
        SELECT id INTO v_liquidacion_id FROM liquidacion WHERE deposito_plazo_fijo_id=v_dpf_id;
        IF v_liquidacion_id IS NULL THEN RAISE EXCEPTION 'No se pudo resolver liquidación DPF %', v_dpf_id; END IF;
        IF NOT EXISTS (SELECT 1 FROM transaccion WHERE liquidacion_id=v_liquidacion_id
                       AND deposito_plazo_fijo_id=v_dpf_id AND tipo='DEPOSITO' AND canal='WEB') THEN
            INSERT INTO transaccion (tipo, monto, canal, fecha_hora, moneda_id,
                                     cuenta_ahorro_id, deposito_plazo_fijo_id, liquidacion_id)
            VALUES ('DEPOSITO', v_scenario.monto+v_net, 'WEB', v_timestamp,
                    v_scenario.moneda_id, v_scenario.cuenta_abono_id,
                    v_dpf_id, v_liquidacion_id);
        END IF;
        IF v_scenario.estado = 'RENOVADO'
           AND NOT EXISTS (SELECT 1 FROM transaccion WHERE liquidacion_id=v_liquidacion_id
                           AND deposito_plazo_fijo_id=v_dpf_new_id
                           AND tipo='RETIRO' AND canal='WEB') THEN
            INSERT INTO transaccion (tipo, monto, canal, fecha_hora, moneda_id,
                                     cuenta_ahorro_id, deposito_plazo_fijo_id, liquidacion_id)
            SELECT 'RETIRO', d.monto, 'WEB', d.fecha_inicio::TIMESTAMP + TIME '12:00', d.moneda_id,
                   d.cuenta_origen_id, d.id, v_liquidacion_id
            FROM deposito_plazo_fijo d WHERE d.id=v_dpf_new_id;
        END IF;
    END LOOP;

    -- Arqueo 1 is exactly balanced (BOB 150,000); arqueo 2 has a BOB 100
    -- shortage, authorized by admin@test.com, while USD balances exactly.
    SELECT id INTO v_arqueo1_id FROM arqueo_caja
    WHERE control_caja_id=v_control1_id AND observacion='Seed demo SI2: arqueo turno 1';
    IF v_arqueo1_id IS NULL THEN
        INSERT INTO arqueo_caja (control_caja_id, usuario_id, fecha, cierre,
                                 requiere_supervisor, observacion)
        VALUES (v_control1_id, v_cashier_id, (CURRENT_DATE-2)::TIMESTAMPTZ + TIME '11:00',
                false, false, 'Seed demo SI2: arqueo turno 1') RETURNING id INTO v_arqueo1_id;
        INSERT INTO arqueo_caja_moneda (arqueo_id, moneda_id, saldo_teorico,
                                        total_contado, diferencia, resultado)
        VALUES (v_arqueo1_id, v_bob_id, 150000.00, 150000.00, 0.00, 'CUADRADO');
        SELECT id INTO v_account_id FROM arqueo_caja_moneda WHERE arqueo_id=v_arqueo1_id AND moneda_id=v_bob_id;
        INSERT INTO arqueo_caja_detalle (arqueo_moneda_id, tipo, denominacion, cantidad, subtotal)
        VALUES (v_account_id, 'BILLETE', 200.00, 750, 150000.00);
    END IF;

    SELECT id INTO v_arqueo2_id FROM arqueo_caja
    WHERE control_caja_id=v_control2_id AND observacion='Seed demo SI2: arqueo turno 2';
    IF v_arqueo2_id IS NULL THEN
        INSERT INTO arqueo_caja (control_caja_id, usuario_id, supervisor_id, fecha,
                                 fecha_autorizacion, cierre, requiere_supervisor, observacion)
        VALUES (v_control2_id, v_cashier_id, v_admin_id,
                (CURRENT_DATE-1)::TIMESTAMPTZ + TIME '11:00',
                (CURRENT_DATE-1)::TIMESTAMPTZ + TIME '11:01', false, true,
                'Seed demo SI2: arqueo turno 2') RETURNING id INTO v_arqueo2_id;
        INSERT INTO arqueo_caja_moneda (arqueo_id, moneda_id, saldo_teorico,
                                        total_contado, diferencia, resultado)
        VALUES (v_arqueo2_id, v_bob_id, 700.00, 600.00, -100.00, 'FALTANTE'),
               (v_arqueo2_id, v_usd_id, 100.00, 100.00, 0.00, 'CUADRADO');
        SELECT id INTO v_account_id FROM arqueo_caja_moneda WHERE arqueo_id=v_arqueo2_id AND moneda_id=v_bob_id;
        INSERT INTO arqueo_caja_detalle (arqueo_moneda_id, tipo, denominacion, cantidad, subtotal)
        VALUES (v_account_id, 'BILLETE', 200.00, 3, 600.00);
        SELECT id INTO v_account_id FROM arqueo_caja_moneda WHERE arqueo_id=v_arqueo2_id AND moneda_id=v_usd_id;
        INSERT INTO arqueo_caja_detalle (arqueo_moneda_id, tipo, denominacion, cantidad, subtotal)
        VALUES (v_account_id, 'BILLETE', 100.00, 1, 100.00);
    END IF;

    -- Formal close sheets and their per-currency totals.
    SELECT id INTO v_cierre1_id FROM cierre_caja WHERE control_caja_id=v_control1_id;
    IF v_cierre1_id IS NULL THEN
        INSERT INTO cierre_caja (control_caja_id, arqueo_id, usuario_id, fecha, observacion)
        VALUES (v_control1_id, v_arqueo1_id, v_cashier_id,
                (CURRENT_DATE-2)::TIMESTAMPTZ + TIME '11:05',
                'Seed demo SI2: cierre turno 1') RETURNING id INTO v_cierre1_id;
        INSERT INTO cierre_caja_moneda (cierre_id, moneda_id, monto_apertura,
            total_depositos, cantidad_depositos, total_retiros, cantidad_retiros,
            cantidad_transferencias, saldo_teorico, total_contado, diferencia, traspaso_boveda)
        VALUES (v_cierre1_id, v_bob_id, 1000.00, 150000.00, 3, 1000.00, 1, 1,
                150000.00, 150000.00, 0.00, 150000.00);
    END IF;
    SELECT id INTO v_cierre2_id FROM cierre_caja WHERE control_caja_id=v_control2_id;
    IF v_cierre2_id IS NULL THEN
        INSERT INTO cierre_caja (control_caja_id, arqueo_id, usuario_id, fecha, observacion)
        VALUES (v_control2_id, v_arqueo2_id, v_cashier_id,
                (CURRENT_DATE-1)::TIMESTAMPTZ + TIME '11:05',
                'Seed demo SI2: cierre turno 2') RETURNING id INTO v_cierre2_id;
        INSERT INTO cierre_caja_moneda (cierre_id, moneda_id, monto_apertura,
            total_depositos, cantidad_depositos, total_retiros, cantidad_retiros,
            cantidad_transferencias, saldo_teorico, total_contado, diferencia, traspaso_boveda)
        VALUES (v_cierre2_id, v_bob_id, 500.00, 500.00, 1, 300.00, 1, 0,
                700.00, 600.00, -100.00, 600.00),
               (v_cierre2_id, v_usd_id, 0.00, 100.00, 1, 0.00, 0, 0,
                100.00, 100.00, 0.00, 100.00);
    END IF;

    -- Contribution certificates use the cooperative sequence. The natural
    -- key is socio + amount/title signature; there is no unique cert number.
    INSERT INTO secuencia_documento (cooperativa_id, tipo, siguiente)
    SELECT v_coop_id::INT, 'CERTIFICADO_APORTACION',
           COALESCE((SELECT max(correlativo)+1 FROM certificado_aportacion ca
                     JOIN socio s ON s.id=ca.socio_id WHERE s.cooperativa_id=v_coop_id),1)
    ON CONFLICT (cooperativa_id, tipo) DO NOTHING;
    UPDATE secuencia_documento sd SET siguiente=GREATEST(sd.siguiente, COALESCE((
        SELECT max(ca.correlativo)+1 FROM certificado_aportacion ca
        JOIN socio s ON s.id=ca.socio_id WHERE s.cooperativa_id=v_coop_id
    ),1)) WHERE sd.cooperativa_id=v_coop_id::INT AND sd.tipo='CERTIFICADO_APORTACION';
    FOR v_scenario IN SELECT * FROM (VALUES
        ('8877001 SC', 500.00, 5, 100.00),
        ('8877003 LP', 300.00, 3, 100.00),
        ('8877006 SC', 250.00, 5, 50.00)
    ) AS certs(ci, total, titles, unit_value)
    LOOP
        SELECT id INTO v_socio_id FROM socio WHERE ci=v_scenario.ci;
        IF NOT EXISTS (SELECT 1 FROM certificado_aportacion
                       WHERE socio_id=v_socio_id AND monto=v_scenario.total
                         AND numero_titulos=v_scenario.titles
                         AND valor_unitario=v_scenario.unit_value
                         ) THEN
            UPDATE secuencia_documento SET siguiente=siguiente+1
            WHERE cooperativa_id=v_coop_id::INT AND tipo='CERTIFICADO_APORTACION'
            RETURNING siguiente-1 INTO v_seq;
            INSERT INTO certificado_aportacion (correlativo, numero_titulos, valor_unitario,
                monto, fecha_emision, estado, socio_id, moneda_id)
            VALUES (v_seq, v_scenario.titles, v_scenario.unit_value, v_scenario.total,
                    CURRENT_DATE-3, 'EMITIDO', v_socio_id, v_bob_id);
        END IF;
    END LOOP;

    -- Pending credit applications with field evaluations; no credit rows are
    -- created because credit workflow is not implemented in this task.
    FOR v_scenario IN SELECT * FROM (VALUES
        ('8877002 SC', 8000.00, 3000.00, 5000.00, 12000.00, 12, 14.50),
        ('8877004 SC', 6500.00, 2500.00, 4000.00,  8000.00, 10, 16.00)
    ) AS requests(ci, income, expense, capacity, amount, months, rate)
    LOOP
        SELECT id INTO v_socio_id FROM socio WHERE ci=v_scenario.ci;
        IF NOT EXISTS (SELECT 1 FROM evaluacion_campo e
                       WHERE e.usuario_id=v_credit_id
                         AND e.ingreso_mensual=v_scenario.income
                         AND e.egreso_mensual=v_scenario.expense
                         AND e.capacidad_pago=v_scenario.capacity
                         AND e.coordenadas='-17.7833,-63.1821') THEN
            INSERT INTO evaluacion_campo (ingreso_mensual, egreso_mensual, capacidad_pago,
                fotografias_respaldo, coordenadas, fecha, resumen_cualitativo_ia, usuario_id)
            VALUES (v_scenario.income, v_scenario.expense, v_scenario.capacity,
                    'negocio_demo.jpg,domicilio_demo.jpg', '-17.7833,-63.1821',
                    CURRENT_DATE-2, 'Actividad estable y capacidad de pago evaluada en campo.', v_credit_id);
        END IF;
        SELECT id INTO v_dpf_id FROM evaluacion_campo e
        WHERE e.usuario_id=v_credit_id
          AND e.ingreso_mensual=v_scenario.income AND e.egreso_mensual=v_scenario.expense
          AND e.capacidad_pago=v_scenario.capacity AND e.coordenadas='-17.7833,-63.1821'
        ORDER BY id LIMIT 1;
        IF NOT EXISTS (SELECT 1 FROM solicitud_credito
                       WHERE socio_id=v_socio_id AND usuario_id=v_credit_id
                         AND evaluacion_campo_id=v_dpf_id AND monto=v_scenario.amount
                         AND plazo_meses=v_scenario.months AND tasa_interes=v_scenario.rate
                         AND estado='PENDIENTE') THEN
            INSERT INTO solicitud_credito (monto, plazo_meses, tasa_interes,
                calificacion_asfi, tiene_deudas, estado, socio_id, usuario_id, evaluacion_campo_id)
            VALUES (v_scenario.amount, v_scenario.months, v_scenario.rate,
                    'B', false, 'PENDIENTE', v_socio_id, v_credit_id, v_dpf_id);
        END IF;
    END LOOP;

    -- Final monotonic sequence safeguards after all seeded certificates.
    UPDATE secuencia_documento sd SET siguiente=GREATEST(sd.siguiente, COALESCE((
        SELECT max(correlativo)+1 FROM certificado_aportacion ca
        JOIN socio s ON s.id=ca.socio_id WHERE s.cooperativa_id=v_coop_id
    ),1)) WHERE sd.cooperativa_id=v_coop_id::INT AND sd.tipo='CERTIFICADO_APORTACION';
    UPDATE secuencia_documento sd SET siguiente=GREATEST(sd.siguiente, COALESCE((
        SELECT max(substring(d.numero_certificado FROM '^DPF-([0-9]{6})$')::INT)+1
        FROM deposito_plazo_fijo d WHERE d.cooperativa_id=v_coop_id
    ),1)) WHERE sd.cooperativa_id=v_coop_id::INT AND sd.tipo='DPF';
    UPDATE secuencia_documento sd SET siguiente=GREATEST(sd.siguiente, COALESCE((
        SELECT max(substring(c.numero FROM ('^CA-' || lpad(v_coop_id::TEXT,3,'0') || '-([0-9]{6})$'))::INT)+1
        FROM cuenta_ahorro c JOIN socio s ON s.id=c.socio_id WHERE s.cooperativa_id=v_coop_id
    ),1)) WHERE sd.cooperativa_id=v_coop_id::INT AND sd.tipo='CUENTA_AHORRO';
END;
$seed$;

COMMIT;

BEGIN;

CREATE TABLE IF NOT EXISTS producto_credito (
    id SERIAL PRIMARY KEY,
    cooperativa_id BIGINT NOT NULL REFERENCES cooperativa(id),
    codigo VARCHAR(20) NOT NULL,
    nombre VARCHAR(100) NOT NULL,
    descripcion TEXT,
    moneda_id INT NOT NULL REFERENCES moneda(id),
    monto_min NUMERIC(14,2) NOT NULL,
    monto_max NUMERIC(14,2) NOT NULL,
    plazo_min_meses INT NOT NULL,
    plazo_max_meses INT NOT NULL,
    tasa_interes_anual NUMERIC(5,2) NOT NULL,
    tipo_amortizacion VARCHAR(10) NOT NULL,
    dias_gracia_mora INT NOT NULL DEFAULT 0,
    tasa_mora_anual NUMERIC(5,2) NOT NULL DEFAULT 0,
    relacion_cuota_ingreso_max NUMERIC(5,2) NOT NULL DEFAULT 40.00,
    requiere_garantia BOOLEAN NOT NULL DEFAULT false,
    estado VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT now(),
    fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_producto_credito_cooperativa_codigo UNIQUE (cooperativa_id, codigo),
    CONSTRAINT chk_producto_credito_amortizacion CHECK (tipo_amortizacion IN ('FRANCES','ALEMAN')),
    CONSTRAINT chk_producto_credito_estado CHECK (estado IN ('ACTIVO','INACTIVO')),
    CONSTRAINT chk_producto_credito_montos CHECK (monto_min > 0 AND monto_min <= monto_max),
    CONSTRAINT chk_producto_credito_plazos CHECK (plazo_min_meses > 0 AND plazo_min_meses <= plazo_max_meses),
    CONSTRAINT chk_producto_credito_tasa CHECK (tasa_interes_anual >= 0 AND tasa_interes_anual <= 100),
    CONSTRAINT chk_producto_credito_tasa_mora CHECK (tasa_mora_anual >= 0 AND tasa_mora_anual <= 100),
    CONSTRAINT chk_producto_credito_ratio CHECK (relacion_cuota_ingreso_max > 0 AND relacion_cuota_ingreso_max <= 100),
    CONSTRAINT chk_producto_credito_gracia CHECK (dias_gracia_mora >= 0)
);

ALTER TABLE solicitud_credito ADD COLUMN IF NOT EXISTS producto_credito_id INT;
DO $$ BEGIN
    ALTER TABLE solicitud_credito
        ADD CONSTRAINT fk_solicitud_credito_producto
        FOREIGN KEY (producto_credito_id) REFERENCES producto_credito(id);
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

INSERT INTO producto_credito
    (cooperativa_id, codigo, nombre, descripcion, moneda_id, monto_min, monto_max,
     plazo_min_meses, plazo_max_meses, tasa_interes_anual, tipo_amortizacion,
     dias_gracia_mora, tasa_mora_anual, relacion_cuota_ingreso_max, requiere_garantia)
SELECT c.id, v.codigo, v.nombre, v.descripcion, m.id, v.monto_min, v.monto_max,
       v.plazo_min, v.plazo_max, v.tasa, v.amortizacion,
       v.gracia, v.mora, v.ratio, v.garantia
FROM cooperativa c
CROSS JOIN (VALUES
    ('CONS-BOB', 'Crédito de Consumo', 'Financiamiento de consumo en bolivianos', 'BOB', 1000.00, 50000.00, 6, 48, 18.00, 'FRANCES', 3, 3.00, 40.00, false),
    ('MICRO-BOB', 'Microcrédito Productivo', 'Capital para actividades productivas en bolivianos', 'BOB', 2000.00, 100000.00, 6, 60, 15.00, 'FRANCES', 5, 3.00, 45.00, true),
    ('VIV-USD', 'Crédito de Vivienda', 'Financiamiento de vivienda en dólares estadounidenses', 'USD', 10000.00, 150000.00, 60, 240, 8.50, 'ALEMAN', 5, 2.00, 35.00, true)
) AS v(codigo, nombre, descripcion, moneda, monto_min, monto_max, plazo_min,
       plazo_max, tasa, amortizacion, gracia, mora, ratio, garantia)
JOIN moneda m ON m.codigo_iso = v.moneda
ON CONFLICT (cooperativa_id, codigo) DO NOTHING;

COMMIT;

BEGIN;

ALTER TABLE solicitud_credito
    ADD COLUMN IF NOT EXISTS numero_solicitud VARCHAR(20),
    ADD COLUMN IF NOT EXISTS destino VARCHAR(20),
    ADD COLUMN IF NOT EXISTS destino_detalle TEXT,
    ADD COLUMN IF NOT EXISTS observaciones TEXT,
    ADD COLUMN IF NOT EXISTS motivo_anulacion TEXT,
    ADD COLUMN IF NOT EXISTS fecha_solicitud TIMESTAMPTZ NOT NULL DEFAULT now(),
    ADD COLUMN IF NOT EXISTS fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT now(),
    ADD COLUMN IF NOT EXISTS moneda_id INT,
    ADD COLUMN IF NOT EXISTS cooperativa_id BIGINT;

DO $$ BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'solicitud_credito'::regclass
          AND conname = 'fk_solicitud_credito_cooperativa'
    ) THEN
        ALTER TABLE solicitud_credito
            ADD CONSTRAINT fk_solicitud_credito_cooperativa
            FOREIGN KEY (cooperativa_id) REFERENCES cooperativa(id);
    END IF;
END $$;

DO $$ BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'solicitud_credito'::regclass
          AND conname = 'fk_solicitud_credito_moneda'
    ) THEN
        ALTER TABLE solicitud_credito
            ADD CONSTRAINT fk_solicitud_credito_moneda
            FOREIGN KEY (moneda_id) REFERENCES moneda(id);
    END IF;
END $$;

ALTER TABLE evaluacion_campo
    ADD COLUMN IF NOT EXISTS socio_id INT,
    ADD COLUMN IF NOT EXISTS cuota_deudas_mensual NUMERIC(12,2) NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS actividad_economica VARCHAR(150),
    ADD COLUMN IF NOT EXISTS fuente_ingresos VARCHAR(20),
    ADD COLUMN IF NOT EXISTS antiguedad_laboral_meses INT,
    ADD COLUMN IF NOT EXISTS calificacion_asfi VARCHAR(1),
    ADD COLUMN IF NOT EXISTS observaciones TEXT;

DO $$ BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'evaluacion_campo'::regclass
          AND conname = 'fk_evaluacion_campo_socio'
    ) THEN
        ALTER TABLE evaluacion_campo
            ADD CONSTRAINT fk_evaluacion_campo_socio
            FOREIGN KEY (socio_id) REFERENCES socio(id);
    END IF;
END $$;

UPDATE solicitud_credito sc
SET cooperativa_id = s.cooperativa_id
FROM socio s
WHERE s.id = sc.socio_id
  AND sc.cooperativa_id IS NULL;

UPDATE solicitud_credito sc
SET moneda_id = p.moneda_id
FROM producto_credito p
WHERE p.id = sc.producto_credito_id
  AND sc.moneda_id IS NULL;

DO $$ BEGIN
    IF EXISTS (
        SELECT 1
        FROM solicitud_credito
        WHERE evaluacion_campo_id IS NOT NULL
        GROUP BY evaluacion_campo_id
        HAVING COUNT(DISTINCT socio_id) > 1
    ) THEN
        RAISE EXCEPTION 'No se puede asociar una evaluación de campo a más de un socio';
    END IF;
END $$;

UPDATE evaluacion_campo e
SET socio_id = (
    SELECT sc.socio_id
    FROM solicitud_credito sc
    WHERE sc.evaluacion_campo_id = e.id
    ORDER BY sc.id
    LIMIT 1
)
WHERE e.socio_id IS NULL
  AND EXISTS (SELECT 1 FROM solicitud_credito sc WHERE sc.evaluacion_campo_id = e.id);

WITH existing_numbers AS (
    SELECT COALESCE(cooperativa_id, 0) AS tenant_id,
           MAX(SUBSTRING(numero_solicitud FROM '^SOL-([0-9]+)$')::BIGINT) AS last_number
    FROM solicitud_credito
    WHERE numero_solicitud ~ '^SOL-[0-9]+$'
    GROUP BY COALESCE(cooperativa_id, 0)
), missing_numbers AS (
    SELECT sc.id,
           COALESCE(sc.cooperativa_id, 0) AS tenant_id,
           COALESCE(en.last_number, 0) + ROW_NUMBER() OVER (
               PARTITION BY COALESCE(sc.cooperativa_id, 0) ORDER BY sc.id
           ) AS number_value
    FROM solicitud_credito sc
    LEFT JOIN existing_numbers en ON en.tenant_id = COALESCE(sc.cooperativa_id, 0)
    WHERE sc.numero_solicitud IS NULL
)
UPDATE solicitud_credito sc
SET numero_solicitud = 'SOL-' || LPAD(mn.number_value::TEXT, 6, '0')
FROM missing_numbers mn
WHERE mn.id = sc.id;

DO $$ BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'solicitud_credito'::regclass
          AND conname = 'uq_solicitud_credito_coop_numero'
    ) THEN
        ALTER TABLE solicitud_credito
            ADD CONSTRAINT uq_solicitud_credito_coop_numero
            UNIQUE (cooperativa_id, numero_solicitud);
    END IF;
END $$;

INSERT INTO secuencia_documento (cooperativa_id, tipo, siguiente)
SELECT COALESCE(cooperativa_id, 0)::INT,
       'SOLICITUD_CREDITO',
       COALESCE(MAX(SUBSTRING(numero_solicitud FROM '^SOL-([0-9]+)$')::INT), 0) + 1
FROM solicitud_credito
WHERE numero_solicitud ~ '^SOL-[0-9]+$'
GROUP BY COALESCE(cooperativa_id, 0)::INT
ON CONFLICT (cooperativa_id, tipo)
DO UPDATE SET siguiente = GREATEST(
    secuencia_documento.siguiente,
    EXCLUDED.siguiente
);

DO $$ BEGIN
    IF EXISTS (
        SELECT socio_id
        FROM solicitud_credito
        WHERE estado IN ('PENDIENTE', 'OBSERVADA', 'EN_EVALUACION')
        GROUP BY socio_id
        HAVING COUNT(*) > 1
    ) THEN
        RAISE EXCEPTION 'No se puede crear índice: hay socios con más de una solicitud en curso';
    END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS uq_solicitud_credito_un_socio_en_curso
    ON solicitud_credito (socio_id)
    WHERE estado IN ('PENDIENTE', 'OBSERVADA', 'EN_EVALUACION');

COMMIT;
BEGIN;

CREATE TABLE IF NOT EXISTS evaluacion_crediticia (
    id BIGSERIAL PRIMARY KEY,
    solicitud_credito_id INT NOT NULL REFERENCES solicitud_credito(id),
    cooperativa_id BIGINT NOT NULL REFERENCES cooperativa(id),
    version_modelo VARCHAR(20) NOT NULL,
    score INT NOT NULL CHECK (score BETWEEN 0 AND 1000),
    dictamen VARCHAR(20) NOT NULL CHECK (dictamen IN ('APROBADO', 'RECHAZADO', 'REVISION_MANUAL')),
    factores JSONB NOT NULL,
    knockouts JSONB NOT NULL,
    explicacion TEXT NOT NULL,
    cuota_estimada NUMERIC(14,2),
    relacion_cuota_ingreso NUMERIC(7,2),
    usuario_id BIGINT NOT NULL REFERENCES usuario(id),
    fecha TIMESTAMPTZ NOT NULL DEFAULT now(),
    resolucion VARCHAR(20) NULL CHECK (resolucion IN ('APROBADO', 'RECHAZADO')),
    resolucion_justificacion TEXT NULL,
    resolucion_usuario_id BIGINT NULL REFERENCES usuario(id),
    resolucion_fecha TIMESTAMPTZ NULL
);

CREATE INDEX IF NOT EXISTS idx_evaluacion_crediticia_solicitud_fecha
    ON evaluacion_crediticia (solicitud_credito_id, fecha DESC);

COMMIT;

BEGIN;

ALTER TABLE credito
    ADD COLUMN IF NOT EXISTS numero_credito VARCHAR(20),
    ADD COLUMN IF NOT EXISTS cooperativa_id BIGINT,
    ADD COLUMN IF NOT EXISTS socio_id INT,
    ADD COLUMN IF NOT EXISTS producto_credito_id INT,
    ADD COLUMN IF NOT EXISTS moneda_id INT,
    ADD COLUMN IF NOT EXISTS tasa_interes NUMERIC(5,2),
    ADD COLUMN IF NOT EXISTS plazo_meses INT,
    ADD COLUMN IF NOT EXISTS tipo_amortizacion VARCHAR(10),
    ADD COLUMN IF NOT EXISTS fecha_desembolso DATE,
    ADD COLUMN IF NOT EXISTS modalidad_desembolso VARCHAR(10),
    ADD COLUMN IF NOT EXISTS cuenta_desembolso_id INT,
    ADD COLUMN IF NOT EXISTS transaccion_desembolso_id INT,
    ADD COLUMN IF NOT EXISTS usuario_id BIGINT,
    ADD COLUMN IF NOT EXISTS fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT now();

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='credito'::regclass AND conname='fk_credito_cooperativa') THEN
        ALTER TABLE credito ADD CONSTRAINT fk_credito_cooperativa FOREIGN KEY (cooperativa_id) REFERENCES cooperativa(id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='credito'::regclass AND conname='fk_credito_socio') THEN
        ALTER TABLE credito ADD CONSTRAINT fk_credito_socio FOREIGN KEY (socio_id) REFERENCES socio(id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='credito'::regclass AND conname='fk_credito_producto_credito') THEN
        ALTER TABLE credito ADD CONSTRAINT fk_credito_producto_credito FOREIGN KEY (producto_credito_id) REFERENCES producto_credito(id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='credito'::regclass AND conname='fk_credito_moneda') THEN
        ALTER TABLE credito ADD CONSTRAINT fk_credito_moneda FOREIGN KEY (moneda_id) REFERENCES moneda(id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='credito'::regclass AND conname='fk_credito_cuenta_desembolso') THEN
        ALTER TABLE credito ADD CONSTRAINT fk_credito_cuenta_desembolso FOREIGN KEY (cuenta_desembolso_id) REFERENCES cuenta_ahorro(id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='credito'::regclass AND conname='fk_credito_transaccion_desembolso') THEN
        ALTER TABLE credito ADD CONSTRAINT fk_credito_transaccion_desembolso FOREIGN KEY (transaccion_desembolso_id) REFERENCES transaccion(id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='credito'::regclass AND conname='fk_credito_usuario') THEN
        ALTER TABLE credito ADD CONSTRAINT fk_credito_usuario FOREIGN KEY (usuario_id) REFERENCES usuario(id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='credito'::regclass AND conname='uq_credito_cooperativa_numero') THEN
        ALTER TABLE credito ADD CONSTRAINT uq_credito_cooperativa_numero UNIQUE (cooperativa_id, numero_credito);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='credito'::regclass AND conname='ck_credito_modalidad_desembolso') THEN
        ALTER TABLE credito ADD CONSTRAINT ck_credito_modalidad_desembolso
            CHECK (modalidad_desembolso IS NULL OR modalidad_desembolso IN ('CUENTA','EFECTIVO'));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='credito'::regclass AND conname='ck_credito_tipo_amortizacion') THEN
        ALTER TABLE credito ADD CONSTRAINT ck_credito_tipo_amortizacion
            CHECK (tipo_amortizacion IS NULL OR tipo_amortizacion IN ('FRANCES','ALEMAN'));
    END IF;
END $$;

ALTER TABLE tabla_amortizacion
    ADD COLUMN IF NOT EXISTS saldo_inicial NUMERIC(14,2),
    ADD COLUMN IF NOT EXISTS saldo_final NUMERIC(14,2),
    ADD COLUMN IF NOT EXISTS monto_pagado NUMERIC(14,2) NOT NULL DEFAULT 0.00;

ALTER TABLE transaccion ADD COLUMN IF NOT EXISTS credito_id INT;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='transaccion'::regclass AND conname='fk_transaccion_credito') THEN
        ALTER TABLE transaccion ADD CONSTRAINT fk_transaccion_credito FOREIGN KEY (credito_id) REFERENCES credito(id);
    END IF;
END $$;

UPDATE credito c
SET cooperativa_id = COALESCE(c.cooperativa_id, sc.cooperativa_id, s.cooperativa_id),
    socio_id = COALESCE(c.socio_id, sc.socio_id),
    producto_credito_id = COALESCE(c.producto_credito_id, sc.producto_credito_id),
    moneda_id = COALESCE(c.moneda_id, sc.moneda_id, pc.moneda_id),
    tasa_interes = COALESCE(c.tasa_interes, sc.tasa_interes),
    plazo_meses = COALESCE(c.plazo_meses, sc.plazo_meses),
    tipo_amortizacion = COALESCE(c.tipo_amortizacion, pc.tipo_amortizacion)
FROM solicitud_credito sc
JOIN socio s ON s.id = sc.socio_id
LEFT JOIN producto_credito pc ON pc.id = sc.producto_credito_id
WHERE sc.id = c.solicitud_credito_id;

-- The legacy demo credit has no tenant references on its request, socio, or product.
-- Attribute only that exact seed row when the canonical natural key is unique.
UPDATE credito c
SET cooperativa_id = (
    SELECT id FROM cooperativa WHERE nombre = 'Cooperativa de Prueba SI2'
)
WHERE c.id = 1
  AND c.solicitud_credito_id = 1
  AND c.cooperativa_id IS NULL
  AND (
      SELECT COUNT(*) FROM cooperativa
      WHERE nombre = 'Cooperativa de Prueba SI2'
  ) = 1;

WITH existing_numbers AS (
    SELECT cooperativa_id,
           COALESCE(MAX(SUBSTRING(numero_credito FROM '^CRE-([0-9]+)$')::BIGINT), 0) AS max_number
    FROM credito
    WHERE cooperativa_id IS NOT NULL AND numero_credito ~ '^CRE-[0-9]+$'
    GROUP BY cooperativa_id
), missing_numbers AS (
    SELECT c.id, c.cooperativa_id,
           COALESCE(en.max_number, 0) + ROW_NUMBER() OVER (
               PARTITION BY c.cooperativa_id ORDER BY c.id
           ) AS number_value
    FROM credito c
    LEFT JOIN existing_numbers en ON en.cooperativa_id = c.cooperativa_id
    WHERE c.cooperativa_id IS NOT NULL AND c.numero_credito IS NULL
)
UPDATE credito c
SET numero_credito = 'CRE-' || LPAD(mn.number_value::TEXT, 6, '0')
FROM missing_numbers mn
WHERE mn.id = c.id;

INSERT INTO secuencia_documento (cooperativa_id, tipo, siguiente)
SELECT cooperativa_id::INT, 'CREDITO',
       COALESCE(MAX(SUBSTRING(numero_credito FROM '^CRE-([0-9]+)$')::INT), 0) + 1
FROM credito
WHERE cooperativa_id IS NOT NULL AND numero_credito ~ '^CRE-[0-9]+$'
GROUP BY cooperativa_id
ON CONFLICT (cooperativa_id, tipo)
DO UPDATE SET siguiente = GREATEST(secuencia_documento.siguiente, EXCLUDED.siguiente);

COMMIT;
BEGIN;

ALTER TABLE pago_cuota
    ADD COLUMN IF NOT EXISTS credito_id INT REFERENCES credito(id),
    ADD COLUMN IF NOT EXISTS cooperativa_id BIGINT REFERENCES cooperativa(id),
    ADD COLUMN IF NOT EXISTS numero_recibo VARCHAR(20),
    ADD COLUMN IF NOT EXISTS modalidad VARCHAR(10),
    ADD COLUMN IF NOT EXISTS monto_total NUMERIC(14,2),
    ADD COLUMN IF NOT EXISTS dias_atraso INT NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS transaccion_id INT REFERENCES transaccion(id),
    ADD COLUMN IF NOT EXISTS usuario_id BIGINT REFERENCES usuario(id);

DO $$ BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'pago_cuota'::regclass
          AND conname = 'uq_pago_cuota_cooperativa_recibo'
    ) THEN
        ALTER TABLE pago_cuota
            ADD CONSTRAINT uq_pago_cuota_cooperativa_recibo
            UNIQUE (cooperativa_id, numero_recibo);
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'pago_cuota'::regclass
          AND conname = 'ck_pago_cuota_modalidad'
    ) THEN
        ALTER TABLE pago_cuota
            ADD CONSTRAINT ck_pago_cuota_modalidad
            CHECK (modalidad IS NULL OR modalidad IN ('EFECTIVO', 'CUENTA'));
    END IF;
END $$;

ALTER TABLE tabla_amortizacion
    ADD COLUMN IF NOT EXISTS fecha_pago TIMESTAMPTZ;

ALTER TABLE morosidad
    ADD COLUMN IF NOT EXISTS fecha_actualizacion TIMESTAMPTZ DEFAULT now();

DO $$ BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'morosidad'::regclass
          AND conname = 'uq_morosidad_credito'
    ) AND NOT EXISTS (
        SELECT credito_id FROM morosidad
        GROUP BY credito_id
        HAVING COUNT(*) > 1
    ) THEN
        ALTER TABLE morosidad
            ADD CONSTRAINT uq_morosidad_credito UNIQUE (credito_id);
    END IF;
END $$;

UPDATE pago_cuota p
SET credito_id = ta.credito_id
FROM tabla_amortizacion ta
WHERE ta.id = p.tabla_amortizacion_id
  AND p.credito_id IS NULL;

UPDATE pago_cuota p
SET cooperativa_id = c.cooperativa_id
FROM credito c
WHERE c.id = p.credito_id
  AND p.cooperativa_id IS NULL
  AND c.cooperativa_id IS NOT NULL;

COMMIT;
-- CU-W23 part 2: re-credit offers and advisory synthetic default predictions.
CREATE TABLE IF NOT EXISTS prediccion_de_morosidad (
    id BIGSERIAL PRIMARY KEY,
    credito_id INT NOT NULL REFERENCES credito(id) ON DELETE CASCADE,
    probabilidad_mora NUMERIC(5,4) NOT NULL,
    nivel_riesgo VARCHAR(10) NOT NULL,
    version_modelo VARCHAR(20),
    fecha TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE prediccion_de_morosidad ADD COLUMN IF NOT EXISTS probabilidad_mora NUMERIC(5,4);
ALTER TABLE prediccion_de_morosidad ADD COLUMN IF NOT EXISTS nivel_riesgo VARCHAR(10);
-- Preserve/backfill legacy spellings when the table predates this migration.
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'prediccion_de_morosidad' AND column_name = 'probabilidad_de_incumplimiento') THEN
        EXECUTE 'UPDATE prediccion_de_morosidad SET probabilidad_mora = probabilidad_de_incumplimiento WHERE probabilidad_mora IS NULL';
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'prediccion_de_morosidad' AND column_name = 'nivel_de_riesgo') THEN
        EXECUTE 'UPDATE prediccion_de_morosidad SET nivel_riesgo = nivel_de_riesgo WHERE nivel_riesgo IS NULL';
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'prediccion_de_morosidad' AND column_name = 'probabilidad_de_incumplimiento') THEN
        EXECUTE 'ALTER TABLE prediccion_de_morosidad ALTER COLUMN probabilidad_de_incumplimiento DROP NOT NULL';
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'prediccion_de_morosidad' AND column_name = 'nivel_de_riesgo') THEN
        EXECUTE 'ALTER TABLE prediccion_de_morosidad ALTER COLUMN nivel_de_riesgo DROP NOT NULL';
    END IF;
END $$;
ALTER TABLE prediccion_de_morosidad ADD COLUMN IF NOT EXISTS version_modelo VARCHAR(20);
ALTER TABLE prediccion_de_morosidad ADD COLUMN IF NOT EXISTS fecha TIMESTAMPTZ NOT NULL DEFAULT now();
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM prediccion_de_morosidad GROUP BY credito_id HAVING count(*) > 1) THEN
        CREATE UNIQUE INDEX IF NOT EXISTS uq_prediccion_morosidad_credito ON prediccion_de_morosidad(credito_id);
    END IF;
END $$;
ALTER TABLE evaluacion_crediticia ADD COLUMN IF NOT EXISTS probabilidad_mora NUMERIC(5,4);
ALTER TABLE evaluacion_crediticia ADD COLUMN IF NOT EXISTS nivel_riesgo VARCHAR(10);
ALTER TABLE evaluacion_crediticia ADD COLUMN IF NOT EXISTS version_modelo_mora VARCHAR(20);
CREATE TABLE IF NOT EXISTS oferta_recredito (
    id BIGSERIAL PRIMARY KEY,
    cooperativa_id BIGINT NOT NULL REFERENCES cooperativa(id),
    socio_id INT NOT NULL REFERENCES socio(id),
    credito_origen_id INT NOT NULL REFERENCES credito(id),
    producto_credito_id INT NOT NULL REFERENCES producto_credito(id),
    monto_sugerido NUMERIC(14,2) NOT NULL,
    plazo_meses INT NOT NULL,
    tasa_interes NUMERIC(5,2) NOT NULL,
    cuota_estimada NUMERIC(14,2) NOT NULL,
    probabilidad_mora NUMERIC(5,4),
    nivel_riesgo VARCHAR(10),
    motivos JSONB NOT NULL,
    estado VARCHAR(12) NOT NULL DEFAULT 'VIGENTE' CHECK (estado IN ('VIGENTE','ACEPTADA','DESCARTADA','EXPIRADA')),
    fecha_generacion TIMESTAMPTZ NOT NULL DEFAULT now(),
    fecha_vencimiento DATE NOT NULL,
    solicitud_generada_id INT REFERENCES solicitud_credito(id),
    usuario_id BIGINT REFERENCES usuario(id),
    motivo_descarte TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_oferta_recredito_vigente_socio ON oferta_recredito(socio_id) WHERE estado = 'VIGENTE';
-- CU-W25: committee-based credit approval. Safe to apply repeatedly.
BEGIN;

DO $$ BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'producto_credito'
          AND column_name = 'monto_aprobacion_directa'
    ) THEN
        ALTER TABLE producto_credito ADD COLUMN IF NOT EXISTS monto_aprobacion_directa NUMERIC(14,2) NOT NULL DEFAULT 0.00;
        UPDATE producto_credito pc
        SET monto_aprobacion_directa = CASE pc.codigo
            WHEN 'CONS-BOB' THEN 20000.00
            WHEN 'MICRO-BOB' THEN 30000.00
            WHEN 'VIV-USD' THEN 0.00
        END
        WHERE pc.codigo IN ('CONS-BOB', 'MICRO-BOB', 'VIV-USD');
    END IF;
END $$;

ALTER TABLE solicitud_credito
    ADD COLUMN IF NOT EXISTS ronda_comite INT NOT NULL DEFAULT 0;
ALTER TABLE solicitud_credito
    ADD COLUMN IF NOT EXISTS resultado_comite VARCHAR(12);
ALTER TABLE solicitud_credito
    ADD COLUMN IF NOT EXISTS fecha_resolucion_comite TIMESTAMPTZ;

CREATE UNIQUE INDEX IF NOT EXISTS uq_solicitud_credito_id_cooperativa
    ON solicitud_credito(id, cooperativa_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_usuario_id_cooperativa
    ON usuario(id, cooperativa_id);

CREATE TABLE IF NOT EXISTS voto_comite (
    id BIGSERIAL PRIMARY KEY,
    solicitud_credito_id INT NOT NULL,
    cooperativa_id BIGINT NOT NULL REFERENCES cooperativa(id),
    ronda INT NOT NULL CHECK (ronda > 0),
    usuario_id BIGINT NOT NULL,
    voto VARCHAR(10) NOT NULL CHECK (voto IN ('APROBAR','RECHAZAR','OBSERVAR')),
    comentario TEXT NOT NULL CHECK (char_length(btrim(comentario)) >= 10),
    fecha TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_voto_comite_solicitud_ronda_usuario UNIQUE (solicitud_credito_id, ronda, usuario_id),
    CONSTRAINT fk_voto_comite_solicitud_cooperativa
        FOREIGN KEY (solicitud_credito_id, cooperativa_id)
        REFERENCES solicitud_credito(id, cooperativa_id),
    CONSTRAINT fk_voto_comite_usuario_cooperativa
        FOREIGN KEY (usuario_id, cooperativa_id)
        REFERENCES usuario(id, cooperativa_id)
);

CREATE INDEX IF NOT EXISTS idx_voto_comite_solicitud_ronda_fecha
    ON voto_comite(solicitud_credito_id, ronda, fecha, id);

-- Include committee-held requests in the existing single-open-request invariant.
DROP INDEX IF EXISTS uq_solicitud_credito_un_socio_en_curso;
DO $$ BEGIN
    IF EXISTS (
        SELECT socio_id FROM solicitud_credito
        WHERE estado IN ('PENDIENTE', 'OBSERVADA', 'EN_EVALUACION', 'EN_COMITE')
        GROUP BY socio_id HAVING COUNT(*) > 1
    ) THEN
        RAISE EXCEPTION 'No se puede crear índice: hay socios con más de una solicitud en curso';
    END IF;
END $$;
CREATE UNIQUE INDEX uq_solicitud_credito_un_socio_en_curso
    ON solicitud_credito(socio_id)
    WHERE estado IN ('PENDIENTE', 'OBSERVADA', 'EN_EVALUACION', 'EN_COMITE');

COMMIT;
-- CU-W28: idempotent additions for arrears monitoring and collection management.
CREATE TABLE IF NOT EXISTS alerta_credito (
    id BIGSERIAL PRIMARY KEY,
    cooperativa_id BIGINT NOT NULL REFERENCES cooperativa(id),
    credito_id INT NOT NULL REFERENCES credito(id),
    tabla_amortizacion_id INT NULL REFERENCES tabla_amortizacion(id),
    tipo VARCHAR(20) NOT NULL CHECK (tipo IN ('CUOTA_POR_VENCER','CUOTA_VENCIDA','MORA','RIESGO_ALTO')),
    severidad VARCHAR(12) NOT NULL CHECK (severidad IN ('INFO','ADVERTENCIA','CRITICA')),
    mensaje TEXT NOT NULL,
    datos JSONB NOT NULL DEFAULT '{}',
    estado VARCHAR(12) NOT NULL DEFAULT 'ACTIVA' CHECK (estado IN ('ACTIVA','ATENDIDA','DESCARTADA','RESUELTA')),
    fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT now(),
    fecha_cierre TIMESTAMPTZ NULL,
    usuario_cierre_id BIGINT NULL REFERENCES usuario(id),
    comentario_cierre TEXT NULL,
    gestion_id INT NULL REFERENCES historial_gestion_de_cobranza(id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_alerta_credito_activa_clave
    ON alerta_credito (credito_id, tipo, (COALESCE(tabla_amortizacion_id, 0)))
    WHERE estado = 'ACTIVA';
CREATE INDEX IF NOT EXISTS ix_alerta_credito_cooperativa_estado
    ON alerta_credito (cooperativa_id, estado, fecha_creacion DESC);

ALTER TABLE historial_gestion_de_cobranza
    ADD COLUMN IF NOT EXISTS cooperativa_id BIGINT REFERENCES cooperativa(id);
ALTER TABLE historial_gestion_de_cobranza
    ADD COLUMN IF NOT EXISTS usuario_id BIGINT REFERENCES usuario(id);
ALTER TABLE historial_gestion_de_cobranza
    ADD COLUMN IF NOT EXISTS fecha TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE historial_gestion_de_cobranza
    ADD COLUMN IF NOT EXISTS alerta_id BIGINT NULL;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = current_schema() AND table_name = 'producto_credito'
          AND column_name = 'cobertura_minima_garantia'
    ) THEN
        ALTER TABLE producto_credito
            ADD COLUMN cobertura_minima_garantia NUMERIC(6,2) NOT NULL DEFAULT 100.00;
        UPDATE producto_credito
        SET cobertura_minima_garantia = CASE codigo
            WHEN 'MICRO-BOB' THEN 100.00
            WHEN 'VIV-USD' THEN 125.00
            WHEN 'CONS-BOB' THEN 0.00
            ELSE 100.00
        END
        WHERE codigo IN ('MICRO-BOB', 'VIV-USD', 'CONS-BOB');
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS garantia (
    id BIGSERIAL PRIMARY KEY,
    cooperativa_id BIGINT NOT NULL REFERENCES cooperativa(id),
    solicitud_credito_id INT NOT NULL REFERENCES solicitud_credito(id),
    tipo VARCHAR(12) NOT NULL CHECK (tipo IN ('HIPOTECARIA','PRENDARIA','PERSONAL')),
    descripcion TEXT NOT NULL,
    moneda_id INT NOT NULL REFERENCES moneda(id),
    valor_comercial NUMERIC(14,2),
    valor_realizable NUMERIC(14,2) NOT NULL,
    documento_referencia VARCHAR(120),
    avalista_nombre VARCHAR(150),
    avalista_ci VARCHAR(20),
    avalista_ingreso_mensual NUMERIC(14,2),
    avalista_relacion VARCHAR(60),
    avalista_telefono VARCHAR(30),
    socio_avalista_id INT REFERENCES socio(id),
    estado VARCHAR(12) NOT NULL DEFAULT 'REGISTRADA'
        CHECK (estado IN ('REGISTRADA','VERIFICADA','RECHAZADA','LIBERADA')),
    observacion_verificacion TEXT,
    usuario_registro_id BIGINT NOT NULL REFERENCES usuario(id),
    usuario_verificacion_id BIGINT REFERENCES usuario(id),
    fecha_registro TIMESTAMPTZ NOT NULL DEFAULT now(),
    fecha_verificacion TIMESTAMPTZ,
    fecha_liberacion TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS ix_garantia_coop_solicitud
    ON garantia (cooperativa_id, solicitud_credito_id);
