UPDATE morosidad
   SET estado = CASE WHEN dias_de_retaso > 0
                     THEN 'EN_MORA' ELSE 'AL_DIA' END
 WHERE estado NOT IN ('AL_DIA', 'EN_MORA')
    OR estado IS NULL;

