                     THEN 'EN_MORA' ELSE 'AL_DIA' END
 WHERE estado NOT IN ('AL_DIA', 'EN_MORA')
    OR estado IS NULL;

UPDATE morosidad m
   SET estado = 'EN_MORA'
  FROM credito c
 WHERE c.id = m.credito_id
   AND c.estado = 'EN_MORA';

UPDATE credito
   SET estado = 'VIGENTE'
 WHERE estado = 'EN_MORA';

